//   ilias  – ILIAS-Übungstest Privatrecht (Lösung aus der Rückmeldung übernommen)
//   blatt  – „Testfragen Bürgerliches Recht“ mit Lösungsspalte (Lösung übernommen, geprüft)
//   erb    – „Testfragen“ Erbrecht/Erbschaftsteuer (Richtig/Falsch-Liste)

const QUELLEN = {
  pdf: "Testfragen-PDF",
  klausur: "Klausur 2020",
  ilias: "ILIAS-Übungstest",
  blatt: "Testfragen BGB",
  erb: "Erbrecht"
};

const RF = ["Richtig", "Falsch"];

const FRAGEN = [

// ===================== Privatrecht_Testfragen.pdf =====================
{id:"p01",s:"pdf",q:"V verkauft an Christi Himmelfahrt („Vatertag“) sein Auto für 200 € an seinen Zechkumpanen K; dabei ist V durch den Genuss geistiger Getränke in einem Zustand vorübergehender Störung der Geistestätigkeit. Tags darauf holt K das Auto beim inzwischen wieder nüchternen V ab, der mit der Übergabe zähneknirschend einverstanden ist, und verspricht: „Morgen zahle ich“. Wie ist die Rechtslage?",
 o:["V kann von K die Zahlung von 200 € verlangen, § 433 (2).","K ist nicht Eigentümer des Autos geworden, weil der Kaufvertrag unwirksam ist.","K ist Eigentümer des Autos geworden.","Durch die Übereignung des Autos ist der Kaufvertrag wirksam geworden.","V kann ggf. die Herausgabe des Autos von K verlangen."],
 a:[2,4],e:"Der Kaufvertrag ist nach § 105 Abs. 2 BGB nichtig (vorübergehende Störung der Geistestätigkeit). Die Übereignung am nächsten Tag (V ist nüchtern) ist wegen des Abstraktionsprinzips trotzdem wirksam – K ist Eigentümer. Weil der rechtliche Grund fehlt, kann V das Auto nach § 812 Abs. 1 S. 1 Alt. 1 BGB herausverlangen. Die Übereignung „heilt“ den Kaufvertrag nicht."},
{id:"p02",s:"pdf",q:"Der Minderjährige M mietet von seinen Ersparnissen ein Mountainbike.",
 o:["Der Mietvertrag ist stets wirksam, wenn M den Mietzins entrichtet hat.","Falls M 14 Jahre alt ist, ist der Mietvertrag auf jeden Fall auch ohne Zustimmung der Eltern wirksam (wegen des „Taschengeldparagraphen“).","Die Überlassung des Mountainbikes ist für M lediglich rechtlich vorteilhaft; als beschränkt Geschäftsfähiger kann er deswegen den Mietvertrag auch ohne Beteiligung seiner Eltern abschließen.","Der Mietvertrag ist stets unwirksam und kann auch nicht wirksam werden.","Keine der vorgenannten Antworten ist richtig."],
 a:[4],e:"Der Mietvertrag verpflichtet M zur Zahlung – er ist nicht lediglich rechtlich vorteilhaft (§ 107 BGB). § 110 BGB greift nur, wenn die Mittel zu diesem Zweck oder zur freien Verfügung überlassen wurden, und hilft einem Kind unter 7 gar nicht. Der Vertrag kann aber durch Genehmigung der Eltern wirksam werden (§ 108 BGB) – „stets unwirksam“ ist also auch falsch."},
{id:"p03",s:"pdf",q:"Was stimmt?",
 o:["Wer sich in einem Zustand dauerhafter Störung der Geistestätigkeit im Sinne des § 104 Nr. 2 BGB befindet, ist nicht rechtsfähig.","Ein Geschäftsunfähiger kann ausnahmsweise wirksame Willenserklärungen abgeben.","Einfache, verständliche Willenserklärungen eines Sechsjährigen können wirksam sein.","Die Rechtsgeschäfte eines Siebenjährigen können wirksam sein.","Keine der vorgenannten Antworten stimmt."],
 a:[1,3],e:"Rechtsfähig ist jeder Mensch ab Vollendung der Geburt (§ 1 BGB). Ausnahme für volljährige Geschäftsunfähige: Geschäfte des täglichen Lebens mit geringwertigen Mitteln (§ 105a BGB). Ein Sechsjähriger ist geschäftsunfähig (§ 104 Nr. 1), seine Erklärungen sind nichtig (§ 105 Abs. 1). Ab 7 ist man beschränkt geschäftsfähig (§ 106) – Geschäfte können nach §§ 107 ff. wirksam sein."},
{id:"p04",s:"pdf",q:"Ein Bürgschaftsvertrag …",
 o:["… ist nur wirksam, falls er von beiden Parteien unterschrieben wird.","… kann in elektronischer Form geschlossen werden.","… ist wirksam, wenn die schriftlichen Erklärungen notariell beglaubigt sind.","… kann im Rahmen eines gerichtlichen Vergleichs wirksam abgeschlossen werden.","… kann in Textform geschlossen werden."],
 a:[2,3],e:"§ 766 BGB: Nur die Erklärung des Bürgen braucht die Schriftform, die elektronische Form ist ausdrücklich ausgeschlossen (Textform reicht erst recht nicht). Notarielle Beglaubigung/Beurkundung ersetzt die Schriftform (§§ 126 Abs. 4, 129 BGB), ebenso ein gerichtlich protokollierter Vergleich (§ 127a BGB)."},
{id:"p05",s:"pdf",q:"Sie haben Ihren Eltern versprochen, sich um die Kündigung des viel zu teuren DSL-Vertrags zu kümmern. Heute läuft die Kündigungsfrist ab, laut AGB droht die Vertragsverlängerung um ein Jahr. Ein Blick in den Vertrag verrät: Die Kündigung muss in Schriftform erfolgen. Was tun?",
 o:["Ein Kündigungsschreiben losschicken – es zählt ja das Datum des Poststempels.","Eine Kündigungsmail schicken.","Ein Kündigungsfax schicken.","Es gibt keine Möglichkeit mehr, rechtzeitig zu kündigen.","Keine der vorgenannten Antworten ist richtig."],
 a:[4],e:"Lösung laut PDF: E. Der Poststempel zählt nicht – die Kündigung wird erst mit Zugang wirksam (§ 130 BGB). Eine rechtzeitige Kündigung ist noch möglich, z. B. indem man das unterschriebene Schreiben heute persönlich in den Briefkasten des Anbieters wirft. Hinweis: Bei nur vertraglich vereinbarter Schriftform genügt nach § 127 Abs. 2 BGB grundsätzlich auch telekommunikative Übermittlung, und gegenüber Verbrauchern darf in AGB seit 2016 höchstens Textform verlangt werden (§ 309 Nr. 13 BGB) – die Musterlösung wertet Mail und Fax trotzdem nicht als richtig."},
{id:"p06",s:"pdf",q:"Der Verkäufer bietet dem Käufer am 24.01.01 seine Ware an; der Käufer teilt dem Verkäufer mit Schreiben vom 27.01.01 mit, dass er zustimmt, sein Brief kommt erst am Abend des 30.01.01 beim Verkäufer an. Am 01.02.01 übergibt der Verkäufer die Ware an einen Transportunternehmer. Ab wann ist der Käufer Eigentümer der Ware?",
 o:["Ab 24.01.01.","Ab 27.01.01.","Ab 30.01.01.","Ab 01.02.01.","Zu keinem der genannten Daten."],
 a:[4],e:"Der Kaufvertrag (Verpflichtungsgeschäft) überträgt noch kein Eigentum. Eigentum geht erst durch Einigung und Übergabe an den Käufer über (§ 929 S. 1 BGB). Die Übergabe an den Transportunternehmer ist keine Übergabe an den Käufer."},
{id:"p07",s:"pdf",q:"Verpflichtungsgeschäft ist …",
 o:["… ein Kaufvertrag.","… ein Schenkungsvertrag.","… die Übereignung der verschenkten Sache.","… ein Pachtvertrag.","… die Abtretung (= Übertragung) einer Forderung."],
 a:[0,1,3],e:"Kauf-, Schenkungs- und Pachtvertrag begründen Pflichten (Verpflichtungsgeschäfte). Die Übereignung (§ 929) und die Abtretung (§ 398) übertragen ein Recht – das sind Verfügungsgeschäfte."},
{id:"p08",s:"pdf",q:"A bestellt beim Versandhändler V Kleidung mit einem am PC geschriebenen Brief. Seine Bestellung trägt das Datum 03.09.; A wirft sie am 04.09. in den Briefkasten der Post; aufgrund eines Streiks am 04. und 05.09. wird sein Schreiben allerdings erst am Vormittag des 06.09. in den Briefkasten des V eingeworfen. Was gilt?",
 o:["A hat kein wirksames Angebot abgegeben, da er nicht handschriftlich unterschrieben hat.","Die Willenserklärung des A wurde am 03.09. abgegeben.","Die Willenserklärung des A ist dem V am 05.09. zugegangen; „Sonderereignisse“ wie der Streik sind unbeachtlich.","Die Willenserklärung des A ist dem V am 07.09. zugegangen, da bei Versendung mit der Post eine Drei-Tages-Fiktion gilt.","Die Willenserklärung des A ist dem V am 06.09. zugegangen."],
 a:[4],e:"Ein Kaufvertrag ist formfrei, eine Unterschrift ist nicht nötig. Abgegeben ist die Erklärung, wenn A sie willentlich auf den Weg bringt (04.09.). Zugegangen (§ 130 BGB) ist sie, wenn sie so in den Machtbereich des V gelangt, dass unter normalen Umständen mit Kenntnisnahme zu rechnen ist – vormittags im Geschäftsbriefkasten also am 06.09. Eine „Drei-Tages-Fiktion“ gibt es im BGB nicht (nur im Verwaltungs-/Steuerrecht)."},
{id:"p09",s:"pdf",q:"M unterschreibt in der Ludwigshafener Fußgängerzone am Stand eines Automobilclubs eine Erklärung, die er für eine (rechtlich unverbindliche) Unterschriftensammlung gegen die Sperrung der Rheinbrücke hält. In Wirklichkeit handelt es sich allerdings um ein Formular zur Aufnahme als neues Mitglied des Automobilclubs, was für M erkennbar gewesen wäre, wenn er die Erklärung gelesen hätte. Was ist richtig?",
 o:["M hat nichts erklärt, sondern nur eine Unterschrift geleistet; also liegt keine Willenserklärung vor.","Mangels Handlungswille des M liegt keine wirksame Willenserklärung vor.","Mangels Erklärungsbewusstsein des M liegt keine wirksame Willenserklärung vor.","Es liegt eine wirksame Willenserklärung vor.","Allein schon mit seiner Unterschrift wurde M Mitglied des ADAC."],
 a:[3],e:"Handlungswille liegt vor (M unterschreibt bewusst). Das fehlende Erklärungsbewusstsein schadet nicht, wenn M bei verkehrsüblicher Sorgfalt hätte erkennen können, dass seine Unterschrift als Willenserklärung verstanden wird („potentielles Erklärungsbewusstsein“). Die Erklärung ist wirksam, aber analog § 119 Abs. 1 BGB anfechtbar. Mitglied wird M erst, wenn der Club den Antrag annimmt."},
{id:"p10",s:"pdf",q:"Was stimmt?",
 o:["Einseitige Rechtsgeschäfte bestehen immer aus nicht empfangsbedürftigen Willenserklärungen.","Das Testament ist ein einseitiges Rechtsgeschäft, das aus einer nicht empfangsbedürftigen Willenserklärung besteht.","Der Kaufvertrag ist ein Rechtsgeschäft, das mit Abgabe der beiden Willenserklärungen wirksam wird.","Die Auslobung ist kein Rechtsgeschäft.","Die Auslobung ist ein Rechtsgeschäft, das mit Abgabe der zugrunde liegenden Willenserklärung wirksam wird."],
 a:[1,4],e:"Es gibt auch einseitige Rechtsgeschäfte mit empfangsbedürftiger Erklärung (z. B. Kündigung). Testament und Auslobung (§ 657 BGB) sind einseitige Rechtsgeschäfte mit nicht empfangsbedürftiger Erklärung – sie werden mit Abgabe wirksam. Beim Kaufvertrag muss die Annahme dem Anbietenden zugehen."},
{id:"p11",s:"pdf",q:"Die Kündigung eines Handy-Vertrages ist …",
 o:["… eine Willenserklärung.","… kein Rechtsgeschäft, sondern ein rein faktisches Verhalten (Realakt).","… ein einseitiges Rechtsgeschäft.","… ein zweiseitiges Rechtsgeschäft, da sie einen Vertrag beendet.","… keinesfalls im BGB geregelt, da dieses aus dem 19. Jahrhundert stammt."],
 a:[0,2],e:"Die Kündigung ist eine einseitige, empfangsbedürftige Willenserklärung und damit ein einseitiges Rechtsgeschäft. Dass sie einen Vertrag betrifft, macht sie nicht zweiseitig."},
{id:"p12",s:"pdf",q:"Welche Aussagen zum Rechtsgeschäft treffen zu?",
 o:["Ein Rechtsgeschäft besteht immer aus mindestens einer Willenserklärung.","Ein Testament wird nur zum Rechtsgeschäft, falls es gefunden wird.","„Rechtsgeschäft“ ist ein anderes Wort für „Vertrag“.","Ein Vertrag ist immer ein Rechtsgeschäft.","Keine dieser Antworten ist richtig."],
 a:[0,3],e:"Jedes Rechtsgeschäft enthält mindestens eine Willenserklärung. Der Vertrag ist ein (mehrseitiges) Rechtsgeschäft – es gibt aber auch einseitige Rechtsgeschäfte, daher sind die Begriffe nicht gleichbedeutend. Das Testament ist nicht empfangsbedürftig und auch ohne Auffinden wirksam."},
{id:"p13",s:"pdf",q:"Wer erlangt die Rechtsfähigkeit wie?",
 o:["Der Mensch mit Vollendung der Geburt.","Die Erbengemeinschaft mit dem Tod des Erblassers.","Die GbR mit Eintragung in das Handelsregister.","Der ideelle („nicht wirtschaftliche“) Verein mit Eintragung in das Vereinsregister.","Keine der vorgenannten Antworten ist richtig."],
 a:[0,3],e:"§ 1 BGB: Mensch mit Vollendung der Geburt. § 21 BGB: Idealverein durch Eintragung ins Vereinsregister. Die Erbengemeinschaft ist nicht rechtsfähig. Eine GbR wird nicht ins Handelsregister eingetragen (seit 2024 optional ins Gesellschaftsregister; rechtsfähig ist sie, wenn sie am Rechtsverkehr teilnimmt, § 705 Abs. 2 BGB)."},
{id:"p14",s:"pdf",q:"Wer ist voll rechtsfähig?",
 o:["Die fünfjährige Annika.","Eine KG.","Der GmbH-Gesellschafter Hans Meier.","Der Miterbe Hans Meier.","Keiner der vorgenannten."],
 a:[0,2,3],e:"Jeder Mensch ist voll rechtsfähig (§ 1 BGB) – unabhängig von Alter oder Rolle. Die KG ist eine Personenhandelsgesellschaft und keine juristische Person; im Kurs gilt sie daher als nur „teilrechtsfähig“ (§ 161 Abs. 2 i. V. m. § 105 Abs. 2 HGB)."},
{id:"p15",s:"pdf",q:"Was trifft NICHT zu? (Anzukreuzen ist, was nicht stimmt.)",
 o:["Das Privatrecht ist Teil des Bürgerlichen Rechts.","Das BGB ist ein Gesetz im formellen Sinn.","Das BGB gilt seit 1896.","Das BGB beinhaltet 5 Abschnitte.","Das BGB ist eine Sammlung von Vorschriften für Einzelfälle."],
 a:[0,2,3,4],e:"Umgekehrt: Das Bürgerliche Recht ist Teil des Privatrechts. Das BGB wurde 1896 verkündet, gilt aber seit 01.01.1900. Es hat 5 Bücher (nicht Abschnitte) und enthält abstrakt-generelle Regeln, keine Einzelfallvorschriften. Als vom Parlament beschlossenes Gesetz ist es ein Gesetz im formellen Sinn."},
{id:"p16",s:"pdf",q:"Was stimmt?",
 o:["Die Unterscheidung zwischen „Öffentlichem Recht“ und „Privatrecht“ wird nur aus formellen Gründen vorgenommen, inhaltlich besteht kein Unterschied.","Der Staat handelt immer öffentlich-rechtlich.","Bürger können auch öffentlich-rechtlich handeln.","Öffentliches Recht wird durch den Staat durchgesetzt, Privatrecht hingegen nicht.","Keine der vorgenannten Antworten."],
 a:[2],e:"Bürger können öffentlich-rechtlich handeln, z. B. als Beliehene (TÜV-Prüfer) oder bei Anträgen an Behörden. Der Staat handelt oft privatrechtlich (Büromaterial kaufen). Auch Privatrecht wird staatlich durchgesetzt (Gerichte, Gerichtsvollzieher). Die Unterscheidung ist inhaltlich bedeutsam (Über-/Unterordnung vs. Gleichordnung)."},

// ===================== Klausur 2020_07_01 GS1 PR (Lösungen erarbeitet) =====================
{id:"k01",s:"klausur",q:"Welche Rechtsnormen gehören zum Privatrecht?",
 o:["Die §§ 373 ff. HGB über den Handelskauf.","Das Jahressteuergesetz, das unter anderem Normen des Einkommensteuergesetzes ändert.","Die Regelung über öffentliche Lasten in § 436 BGB.","Das Strafgesetzbuch.","Die Satzung der Stadt Schifferstadt über die Nutzung der Waldfesthalle durch Private."],
 a:[0,2],e:"Das HGB ist Sonderprivatrecht der Kaufleute. § 436 BGB regelt im Kaufrecht, wer beim Grundstückskauf Erschließungsbeiträge trägt – Privatrecht, trotz des Begriffs „öffentliche Lasten“. Steuerrecht, Strafrecht und eine kommunale Satzung (hoheitliche Regelung der Gemeinde) gehören zum öffentlichen Recht."},
{id:"k02",s:"klausur",q:"Welche Aussage(n) ist / sind zutreffend?",
 o:["Das Steuerrecht knüpft an das Privatrecht an.","Privatrechtliche Handlungen können Bedeutung für die Besteuerung haben.","Privatrecht und Steuerrecht sind Teile verschiedener Rechtsordnungen.","Der steuerliche Gesetzgeber ist immer an die im bürgerlichen Recht getroffenen Regeln über die Zuordnung von Wirtschaftsgütern gebunden.","Privatrecht und Steuerrecht sind Teile einer einheitlichen Rechtsordnung."],
 a:[0,1,4],e:"Steuerrecht knüpft an zivilrechtliche Sachverhalte an (z. B. Kaufvertrag → Umsatzsteuer). Beide sind Teile unserer einheitlichen Rechtsordnung. Das Steuerrecht kann aber abweichen, z. B. wirtschaftliches Eigentum nach § 39 Abs. 2 AO."},
{id:"k03",s:"klausur",q:"Welche Aussage(n) trifft/treffen auf das Bürgerliche Gesetzbuch zu?",
 o:["Es ist Öffentliches Recht, da es für alle Bürger gilt.","Es ist am 23. Mai 1949 in Kraft getreten.","Es sagt, dass Ansprüche wegen der Vertragsfreiheit nur aus Verträgen entstehen können.","Es regelt im Sachenrecht den Kauf von Sachen.","Keine der vorgenannten Antworten ist richtig."],
 a:[4],e:"Das BGB ist Privatrecht und gilt seit 01.01.1900 (23.05.1949 ist das Grundgesetz). Ansprüche entstehen auch aus Gesetz (z. B. § 823, § 812). Der Kauf ist im Schuldrecht geregelt (§§ 433 ff.); das Sachenrecht regelt die Übereignung."},
{id:"k04",s:"klausur",q:"Wer ist rechtsfähig?",
 o:["Die Stadt Ludwigshafen.","Die „Klinikum der Stadt Ludwigshafen“ GmbH.","Der (nicht-wirtschaftliche) „Förderverein Freunde des Klinikums“ e.V.","Der vor einer halben Stunde im Klinikum geborene Säugling A.","Der nur durch Apparate am Leben gehaltene Intensivpatient I."],
 a:[0,1,2,3,4],e:"Die Stadt ist eine juristische Person des öffentlichen Rechts, GmbH (§ 13 GmbHG) und e.V. (§ 21 BGB) sind juristische Personen des Privatrechts. Jeder lebende Mensch ist rechtsfähig (§ 1 BGB) – auch der Säugling und der Intensivpatient, solange er nicht (hirn-)tot ist."},
{id:"k05",s:"klausur",q:"Wer ist voll rechtsfähig?",
 o:["Ein 13-jähriger Schüler.","Eine GbR.","Eine AG.","Ein älterer Mann, der Gesellschafter einer Kommanditgesellschaft ist.","Ein Hund."],
 a:[0,2,3],e:"Menschen (§ 1 BGB) und juristische Personen wie die AG (§ 1 AktG) sind voll rechtsfähig. Die GbR ist eine rechtsfähige Personengesellschaft, aber keine juristische Person (im Kurs: „teilrechtsfähig“). Tiere sind keine Rechtssubjekte (§ 90a BGB)."},
{id:"k06",s:"klausur",q:"Tim ist elf Jahre alt; für sein gutes Zeugnis hat er von seinen Eltern ein neues Fahrrad bekommen, das er eifrig nutzt, um seiner Freundin Maja zu imponieren. Was trifft zu?",
 o:["Tim ist minderjährig und kann deswegen nicht Eigentümer des Fahrrads sein.","Verursacht Tim aus Unachtsamkeit im Straßenverkehr einen Fahrradunfall, hat er den verursachten Schaden auf jeden Fall zu ersetzen.","Geht mit dem Unfall eine Körperverletzung einher, so ist Tim nicht strafmündig.","Schon mit 17 kann Tim Maja wirksam als seine Erbin einsetzen.","Da Tim das Fahrrad von seinen Eltern geschenkt bekommen hat, könnte er es ohne Zustimmung der Eltern wirksam an Maja weiterverschenken."],
 a:[2,3],e:"Tim ist rechtsfähig und kann Eigentümer sein. Mit 11 haftet er nur, wenn er die nötige Einsichtsfähigkeit hat (§ 828 Abs. 3 BGB) – also nicht „auf jeden Fall“. Strafmündig ist man erst ab 14 (§ 19 StGB). Testierfähig ab 16 (§ 2229 Abs. 1 BGB; Minderjährige nur notariell, § 2233). Das Weiterverschenken bringt den Eigentumsverlust – rechtlich nachteilig, also zustimmungsbedürftig (§ 107 BGB)."},
{id:"k07",s:"klausur",q:"Wer erlangt wie die volle Rechtsfähigkeit?",
 o:["Die Erbengemeinschaft durch Eintragung ins Erbenregister.","Der Einzelkaufmann durch Eintragung ins Handelsregister.","Der wirtschaftliche Verein durch staatliche Verleihung.","Der Neugeborene durch Eintragung in das Geburtenregister.","Der Mensch mit Erreichen des 18. Lebensjahres."],
 a:[2],e:"§ 22 BGB: Der wirtschaftliche Verein erlangt Rechtsfähigkeit durch staatliche Verleihung. Die Erbengemeinschaft ist nicht rechtsfähig. Der Einzelkaufmann ist als Mensch schon rechtsfähig; jeder Mensch wird mit Vollendung der Geburt rechtsfähig (§ 1 BGB). Mit 18 wird man voll geschäftsfähig, nicht rechtsfähig."},
{id:"k08",s:"klausur",q:"Welche der folgenden Aussage(n) zur Formbedürftigkeit von Rechtsgeschäften ist/sind zutreffend?",
 o:["Der Kaufvertrag über einen Gebrauchtwagen bedarf zu seiner Wirksamkeit der Textform.","Der Kaufvertrag über ein Grundstück bedarf zu seiner Wirksamkeit der öffentlichen Beglaubigung.","Ein Schenkungsversprechen bedarf zu seiner Wirksamkeit der notariellen Beurkundung; durch Bewirken der versprochenen Leistung wird ein eventueller Formmangel jedoch geheilt.","Ein Testament ist immer formbedürftig.","Für die Wirksamkeit eines Bürgschaftsvertrages bedarf nur die Willenserklärung des Bürgen der Schriftform, die jedoch nicht durch die elektronische Form ersetzt werden kann."],
 a:[2,3,4],e:"Der Autokauf ist formfrei. Grundstückskauf: notarielle Beurkundung (§ 311b BGB) – Beglaubigung reicht nicht. Schenkungsversprechen: § 518 BGB (Heilung durch Bewirken). Testament: eigenhändig (§ 2247) oder notariell (§ 2232); auch Nottestamente haben Formvorschriften. Bürgschaft: § 766 BGB."},
{id:"k09",s:"klausur",q:"Welche der folgenden Aussage(n) ist/sind zutreffend?",
 o:["Aus dem Abstraktionsprinzip folgt, dass ein wirksamer schuldrechtlicher Anspruch zugleich auch zu einem wirksamen Erfüllungsgeschäft führt.","Das Abstraktionsprinzip besagt, dass ein unwirksames Verpflichtungsgeschäft nicht die Unwirksamkeit des Erfüllungsgeschäfts zur Folge hat.","Wer aufgrund eines unwirksamen schuldrechtlichen Vertrags einem anderen eine Sache übereignet, kann diese nach § 812 Abs. 1 Satz 1, 1. Alt. BGB wieder zurückverlangen.","Aus dem Abstraktionsprinzip folgt, dass ein unwirksames Verpflichtungsgeschäft durch die wirksame Vornahme des Erfüllungsgeschäfts geheilt wird.","Abstraktionsprinzip heißt, dass man Pflichten aus Verträgen zu erfüllen hat."],
 a:[1,2],e:"Verpflichtungs- und Verfügungsgeschäft sind rechtlich voneinander unabhängig. Fehlt der Rechtsgrund, wird über die Leistungskondiktion (§ 812 Abs. 1 S. 1 Alt. 1 BGB) rückabgewickelt. Eine „Heilung“ durch Erfüllung gibt es nur in Sonderfällen (z. B. § 311b Abs. 1 S. 2, § 518 Abs. 2)."},
{id:"k10",s:"klausur",q:"Der 6-jährige Elias fährt – trotz mehrfacher Ermahnung durch seine Eltern – auch heute mit seinem Roller ungebremst vom Grundstück seiner Eltern auf die Straße. Ein Fahrer der DHL GmbH wird dadurch zu einem Ausweichmanöver gezwungen, durch das der Transport-Lkw beschädigt wird. Muss Elias Schadensersatz für die Beschädigung des Lkws leisten?",
 o:["Nein, da es gegen Minderjährige generell keine Anspruchsgrundlage gibt.","Nein, da er mit 6 Jahren keinen nennenswerten Schadensersatz leisten kann.","Nein, da nicht er selbst das Eigentum der DHL GmbH verletzt hat, sondern der Fahrer.","Nein, da nur seine Eltern haften, haftet Elias nicht selbst.","Nein, da er gem. § 828 BGB für den Schaden nicht verantwortlich ist."],
 a:[4],e:"Wer das 7. Lebensjahr nicht vollendet hat, ist deliktsunfähig (§ 828 Abs. 1 BGB). Die Eltern haften nur bei einer Verletzung der Aufsichtspflicht (§ 832 BGB) – das ist nicht der Grund, warum Elias nicht haftet. (Hinweis: Eine Billigkeitshaftung nach § 829 BGB ist im Ausnahmefall denkbar.)"},
{id:"k11",s:"klausur",q:"Welche Aussagen sind richtig?",
 o:["Als Volljährige(r) kann man jemand anderen, der 15 Jahre alt ist, ohne weiteres heiraten.","Mit 14 Jahren ist man strafmündig.","Mit 7 Jahren ist man teilrechtsfähig.","Mit 6 Jahren ist man nicht deliktsfähig.","Mit 9 Jahren ist man für Schäden, die man bei einem Unfall mit einem Kraftfahrzeug einem anderen zufügt, grundsätzlich nicht verantwortlich."],
 a:[1,3,4],e:"Ehemündig ist man erst mit 18 (§ 1303 BGB); eine Ehe mit einer unter 16-Jährigen ist sogar unwirksam. Strafmündig ab 14 (§ 19 StGB). Rechtsfähig ist man ab Geburt voll. § 828 Abs. 1 (unter 7: deliktsunfähig) und Abs. 2 (7–9 Jahre: keine Haftung bei Unfällen mit Kfz/Bahnen, außer bei Vorsatz)."},
{id:"k12",s:"klausur",q:"Die Kündigung eines Mietvertrages …",
 o:["… ist ein Rechtsgeschäft.","… ist eine empfangsbedürftige Willenserklärung.","… ist eine Willenserklärung, aber kein Rechtsgeschäft.","… ist ein beidseitiges Rechtsgeschäft, da sie sich auf einen Vertrag bezieht.","… ist kein Rechtsgeschäft, da sie eine tatsächliche Kündigungshandlung voraussetzt."],
 a:[0,1],e:"Die Kündigung ist ein einseitiges Rechtsgeschäft, das aus einer empfangsbedürftigen Willenserklärung besteht."},
{id:"k13",s:"klausur",q:"K kauft in der Apotheke eine Aktions-Flasche Hustensaft für 19,98 €, die ihm auch sofort übereignet wird; er bezahlt mit einem 20 €-Schein und bekommt ein 2-Cent-Stück zurück. Danach bekommt sein kleiner Sohn ein Stück Traubenzucker geschenkt, den er genüsslich auflutscht. Die Wirksamkeit aller Willenserklärungen unterstellt – was gilt?",
 o:["Es liegen zwei Rechtsgeschäfte vor.","Es liegen vier Rechtsgeschäfte vor.","Es liegen sechs Rechtsgeschäfte vor.","Es liegen drei Verfügungsgeschäfte vor.","Es liegen vier Verfügungsgeschäfte vor."],
 a:[2,4],e:"Verpflichtungsgeschäfte: Kaufvertrag und Schenkungsvertrag (2). Verfügungsgeschäfte: Übereignung des Hustensafts, des 20 €-Scheins, des 2-Cent-Stücks und des Traubenzuckers (4). Insgesamt 6 Rechtsgeschäfte."},
{id:"k14",s:"klausur",q:"A macht Urlaub auf einem Kreuzfahrt-Schiff. Das Abendessen findet in drei Schichten statt, für die man sich morgens über eine Liste unverbindlich anmelden kann. A unterschreibt am Montag ungelesen eine Liste, die er für die Anmeldungsliste hält; in Wirklichkeit handelt es sich um die Buchung eines Landausfluges für 200 €. Was gilt?",
 o:["Mangels Handlungswille liegt keine wirksame Willenserklärung des A vor.","A hatte kein Erklärungsbewusstsein und deswegen ist die Buchung des Ausflugs unwirksam.","Die Buchung des Landausflugs ist wirksam, kann von A aber angefochten werden.","A hat sich nicht wirksam zur Teilnahme an dem Landausflug verpflichtet.","Keine der vorgenannten Antworten ist richtig."],
 a:[2],e:"Handlungswille lag vor. Das fehlende Erklärungsbewusstsein ist unschädlich, weil A bei Sorgfalt hätte erkennen können, was er unterschreibt (potentielles Erklärungsbewusstsein). Die Erklärung ist wirksam, A kann sie aber anfechten (§ 119 Abs. 1 BGB, ggf. mit Schadensersatzpflicht nach § 122)."},
{id:"k15",s:"klausur",q:"Die 6-jährige Petra bekommt von ihrer Patentante eine Trompete geschenkt. Die schwerhörige Mutter freut sich, der Vater ist empört. Ihrem Vater zuliebe gibt daraufhin Petra die Trompete der Patentante zurück. Was ist richtig?",
 o:["Petra kann das Schenkungsangebot wirksam annehmen.","Petra kann hierbei keine wirksame Willenserklärung abgeben.","Die Eltern haben als gesetzliche Vertreter für Petra das Schenkungsangebot angenommen.","Petra erwirbt das Eigentum an der Trompete.","Der Schenkungsvertrag i. S. d. § 516 BGB ist wirksam."],
 a:[1],e:"Mit 6 Jahren ist Petra geschäftsunfähig (§ 104 Nr. 1); ihre Erklärungen sind nichtig (§ 105 Abs. 1). § 107 BGB hilft nur beschränkt Geschäftsfähigen. Die Eltern vertreten gemeinschaftlich (§ 1629 Abs. 1 BGB) – der Vater hat nicht mitgewirkt, und bloße Freude der Mutter ist keine Annahmeerklärung. Daher kein wirksamer Schenkungsvertrag und kein Eigentumserwerb."},
{id:"k16",s:"klausur",q:"Die Übereignung einer beweglichen Sache …",
 o:["… ist ein Verpflichtungsgeschäft.","… ist ein Verfügungsgeschäft.","… setzt ein wirksames Verpflichtungsgeschäft voraus.","… kann durch formlose Einigung und Übergabe erfolgen.","Keine der vorgenannten Antworten ist zutreffend."],
 a:[1,3],e:"Die Übereignung ist eine Verfügung (§ 929 S. 1 BGB) und formfrei. Wegen des Abstraktionsprinzips setzt sie kein wirksames Verpflichtungsgeschäft voraus."},
{id:"k17",s:"klausur",q:"K geht am 24.10. in die Buchhandlung des B, um sich den neuesten Krimi seines Lieblingsautors zu kaufen. Die Verkäuferin teilt ihm mit, dass das Buch wegen der regen Nachfrage momentan nicht vorrätig ist, jedoch in einer Woche eine Nachlieferung zu erwarten sei. K bestellt daraufhin das Buch zum Preis von 20 €. Am 31.10. holt K das Buch ab und zahlt den Kaufpreis. Was gilt?",
 o:["Am 24.10. ist kein Kaufvertrag zu Stande gekommen, da nur eine mündliche Vereinbarung getroffen wurde.","Am 31.10. ist mit Zahlung des Kaufpreises ein Kaufvertrag zu Stande gekommen.","Die Zahlung des Kaufpreises am 31.10. ist ein Verfügungsgeschäft.","Durch die Zahlung des Kaufpreises wird K am 31.10. Eigentümer des Buches.","Keine der vorgenannten Antworten ist richtig."],
 a:[2],e:"Der Kaufvertrag kam formfrei schon am 24.10. zustande. Die Zahlung ist die Übereignung des Geldes – ein Verfügungsgeschäft (Erfüllungsgeschäft). Eigentümer des Buches wird K durch Einigung und Übergabe des Buches (§ 929), nicht durch die Zahlung."},
{id:"k18",s:"klausur",q:"Welche der folgenden Rechtsgeschäfte sind Erfüllungsgeschäfte?",
 o:["A übereignet an B durch Einigung und Übergabe gem. § 929 BGB ein Radio.","A kauft bei seinem Autohändler einen neuen „Passat“.","A und B schließen einen Mietvertrag.","A und B schließen einen Tauschvertrag.","Keines der vorgenannten Rechtsgeschäfte."],
 a:[0],e:"Nur die Übereignung ist ein Erfüllungs- (= Verfügungs-)geschäft. Kauf, Miete und Tausch sind Verpflichtungsgeschäfte."},

// ===================== ILIAS-Übungstest (Lösung aus Rückmeldung) =====================
{id:"i01",s:"ilias",q:"Welche Aussage/-n bezüglich eines 17 Jahre alten Mädchens ist/sind richtig?",
 o:["Sie ist beschränkt rechtsfähig.","Sie ist bedingt/beschränkt deliktsfähig.","Sie ist beschränkt geschäftsfähig.","Sie ist noch minderjährig.","Sie kann bereits ohne ihre Eltern ein Testament errichten."],
 a:[1,2,3,4],e:"Rechtsfähig ist man voll ab Vollendung der Geburt. Bedingt deliktsfähig: § 828 Abs. 3 BGB. Beschränkt geschäftsfähig: §§ 106, 2 BGB. Minderjährig bis 18: § 2 BGB. Testierfähig ab 16 ohne Zustimmung der Eltern: § 2229 BGB (aber nur notariell, § 2233 Abs. 1)."},
{id:"i02",s:"ilias",q:"Welche der folgenden Antworten ist richtig?",
 o:["Privatrecht und öffentliches Recht sind Teile zweier unterschiedlicher Rechtsordnungen.","Das Strafgesetzbuch gehört zum Bürgerlichen Recht.","Das Steuerrecht ist an die privatrechtlichen Rechtsfolgen gebunden.","Bürgerliches Recht ist ein Teilrechtsgebiet des Privatrechts.","Der Staat handelt immer öffentlich-rechtlich."],
 a:[3],e:"Privatrecht und öffentliches Recht sind Rechtsgebiete einer einheitlichen Rechtsordnung. Das StGB ist öffentliches Recht. Das Steuerrecht übernimmt grundsätzlich die privatrechtliche Zuordnung (§ 39 Abs. 1 AO), weicht aber oft ab (§ 39 Abs. 2 AO). Das Bürgerliche Recht ist ein Teil des Privatrechts – neben Sonderprivatrecht wie dem Handelsrecht. Kauft der Staat Büromöbel, handelt er privatrechtlich."},
{id:"i03",s:"ilias",q:"Wer erlangt die Rechtsfähigkeit wie?",
 o:["Ein neugeborenes Kind mit Eintragung ins Geburtenregister.","Ein gemeinnütziger Sportverein durch Eintragung ins Vereinsregister.","Eine privatrechtliche Stiftung mit Eintragung ins Stiftungsregister.","Eine GmbH mit Eintragung ins Handelsregister.","Eine Universität mit Eintragung ins Hochschulregister."],
 a:[1,3],e:"Mensch: mit Vollendung der Geburt ohne weitere Voraussetzung. Idealverein: § 21 BGB. Stiftung: durch staatliche Anerkennung (§ 80 BGB). GmbH: § 11 GmbHG. Universität: als juristische Person des öffentlichen Rechts durch Gesetz (Hochschulgesetze der Länder)."},
{id:"i04",s:"ilias",q:"Was stimmt?",
 o:["Ein 9 Jahre altes Kind haftet unter den Voraussetzungen des § 823 immer auf Schadensersatz, wenn es die erforderliche Einsichtsfähigkeit hat.","Ein 17-Jähriger kann schon selbst ohne Einwilligung der Eltern einfache Rechtsgeschäfte vornehmen, für die er bereits die erforderliche Einsichtsfähigkeit hat.","Rechtsgeschäfte eines 6 Jahre alten Grundschulkindes können nur mit vorheriger Einwilligung der Eltern wirksam sein.","Die von einem 7 Jahre alten Kind vorgenommenen Rechtsgeschäfte können wirksam sein.","Ein 6 Jahre altes Kind ist nicht handlungsfähig."],
 a:[3,4],e:"Nicht bei Unfällen im Straßenverkehr (§ 828 Abs. 2 BGB). Bis einschließlich 17 gelten die §§ 107 ff. – egal ob 7 oder 17 Jahre alt, auf „Einsichtsfähigkeit“ kommt es dabei nicht an. Erklärungen eines 6-Jährigen sind immer nichtig (§ 105 Abs. 1). Ein 7-Jähriger kann nach §§ 107 ff. wirksam handeln. Ein 6-Jähriger ist weder geschäfts- noch deliktsfähig (§ 104 Nr. 1, § 828 Abs. 1) – also nicht handlungsfähig."},
{id:"i05",s:"ilias",q:"Welche der folgenden Aussagen ist richtig?",
 o:["Der Kaufvertrag über ein Grundstück bedarf der Schriftform.","Ein ohne die erforderliche Form geschlossener Bürgschaftsvertrag kann niemals wirksam sein.","Bei vertraglich vereinbarter Schriftform gelten die gleichen Anforderungen wie bei der gesetzlich bestimmten Schriftform.","Ein notariell beurkundeter Bürgschaftsvertrag ist wirksam.","Ein Rechtsgeschäft, für das kraft Gesetz Schriftform vorgesehen ist, kann auch wirksam in einem gerichtlich protokollierten Vergleich vorgenommen werden."],
 a:[3,4],e:"Grundstückskauf: notarielle Beurkundung (§ 311b BGB). Bürgschaft: Heilung durch Erfüllung möglich (§ 766 S. 3 BGB). Vereinbarte Schriftform ist erleichtert (§ 127 Abs. 2 BGB). Notarielle Beurkundung ersetzt die Schriftform (§ 126 Abs. 4); der gerichtliche Vergleich ersetzt die Beurkundung (§ 127a) und damit auch die Schriftform."},
{id:"i06",s:"ilias",q:"Tim (7. Geburtstag am 13.3.2020) stiehlt im Spielwarengeschäft ein Spielzeugauto, obwohl er weiß, dass man nicht klauen darf; ein zweites Spielzeugauto möchte er unbedingt haben, obwohl er nicht so viel Geld hat, um es zu kaufen – er kauft es ohne Wissen seiner Eltern. Welche der folgenden Aussagen trifft zu? (Sachverhalt teilweise rekonstruiert)",
 o:["Tim haftet nach § 823 BGB auf Schadensersatz für das gestohlene Spielzeugauto.","Tim wurde am 13.3.2020 beschränkt rechtsfähig.","Tim muss sich wegen des Diebstahls strafrechtlich verantworten.","Tim ist seit 13.3.2020 bedingt deliktsfähig.","Der Kaufvertrag über das Spielzeugauto ist wirksam, da Tim bereits beschränkt geschäftsfähig ist."],
 a:[0,3],e:"Tim ist bedingt deliktsfähig (§ 828 Abs. 3 BGB) und hat laut Sachverhalt die erforderliche Einsicht – er haftet. Rechtsfähig ist er seit Geburt voll; am 13.3.2020 wurde er beschränkt geschäfts- und bedingt deliktsfähig. Strafmündig erst ab 14. Der Kaufvertrag ist nicht lediglich rechtlich vorteilhaft, keine Einwilligung (§ 107), § 110 greift nicht – schwebend unwirksam, genehmigungsfähig nach § 108."},
{id:"i07",s:"ilias",q:"Welche der folgenden Antworten ist richtig?",
 o:["In § 398 BGB ist ein Verfügungsgeschäft geregelt.","Aus dem Abstraktionsprinzip folgt, dass die Unwirksamkeit des Verpflichtungsgeschäfts nicht auch zwangsweise die Unwirksamkeit des Verfügungsgeschäfts zur Folge hat.","Die nach § 929 S. 1 erforderliche Einigung zur Eigentumsübertragung ist in den Fällen des § 930 BGB entbehrlich.","Die Auslobung (§ 657 BGB) ist ein Verpflichtungsgeschäft.","In § 929 S. 1 BGB ist ein Verfügungsgeschäft geregelt."],
 a:[0,1,3,4],e:"§ 398 (Abtretung) überträgt eine Forderung – Verfügung. Abstraktionsprinzip: richtig. Bei § 930 ist die Übergabe entbehrlich (ersetzt durch ein Besitzkonstitut), nicht die Einigung. Die Auslobung begründet die Pflicht zur Zahlung der Belohnung – Verpflichtungsgeschäft (einseitig). § 929 S. 1 überträgt Eigentum – Verfügung."},
{id:"i08",s:"ilias",q:"K bestellt im Internet bei Verkäufer V am 10.5. ein neues Handy auf Rechnung, das von V am 11.5. zum Versand aufgegeben wird und am 12.5. bei K ankommt. Am 13.5. überweist K die Rechnung. Was trifft zu?",
 o:["Bereits am 11.5. mit Versendung des Handys liegt ein wirksamer Kaufvertrag vor.","Der Kaufvertrag ist ein schuldrechtlicher Vertrag.","Mit Ankunft des Handys bei K liegen ein Verpflichtungsgeschäft und ein Verfügungsgeschäft vor.","K wurde erst am 13.5. Eigentümer des Handys, als er auch den Kaufpreis bezahlte.","Das Eigentum am Handy wird hier nach § 929 S. 1 BGB übertragen."],
 a:[0,1,2,4],e:"Angebot des K mit der Bestellung, Annahme des V konkludent durch Versendung (Zugang der Annahme nach § 151 BGB entbehrlich). Der Kaufvertrag ist in § 433 BGB (Schuldrecht) geregelt. Bei Ankunft: Kaufvertrag (Verpflichtung) + Übereignung des Handys (Verfügung); die Zahlung folgt erst später. Eigentum ging schon am 12.5. mit Einigung und Übergabe über (§ 929 S. 1)."},
{id:"i09",s:"ilias",q:"S surft im Internet. Auf einer Website drückt er einen Button, weil er glaubt, dort stünden nur Hinweise zum Mindestalter für diese Seite. In Wirklichkeit steht dort, dass man mit dem Drücken des Buttons einen kostenpflichtigen Abonnementvertrag für die Website abschließt. Was ist richtig? (Sachverhalt teilweise rekonstruiert)",
 o:["Es liegt eine wirksame Willenserklärung des S vor.","Die Willenserklärung des S ist wegen eines abweichenden Geschäftswillens anfechtbar.","Mangels Handlungswille des S liegt keine wirksame Willenserklärung vor.","Mangels Erklärungsbewusstsein des S liegt keine wirksame Willenserklärung vor.","Keine der vorgenannten Antworten ist richtig."],
 a:[0],e:"S hat bewusst gehandelt (Handlungswille). Ihm fehlt das Erklärungsbewusstsein, er hatte aber potentielles Erklärungsbewusstsein – die Willenserklärung ist wirksam, aber anfechtbar. Ein „abweichender Geschäftswille“ ist nicht das Problem, weil schon das Erklärungsbewusstsein fehlt. (Hinweis: Ob gegenüber einem Verbraucher ein Vertrag zustande kommt, regelt zusätzlich die „Button-Lösung“ des § 312j Abs. 3, 4 BGB.)"},
{id:"i10",s:"ilias",q:"K muss bis 31.10. seinen Mobilfunkvertrag kündigen, wenn sich der Vertrag nicht um ein Jahr verlängern soll. K gibt den Brief am 30.10. bei der Post auf. Diese wirft den Brief am Dienstag, 31.10., nachmittags in den Briefkasten des Mobilfunkunternehmens. Ein Mitarbeiter des Mobilfunkunternehmens leert den Briefkasten am 1.11. und liest die Kündigung. Was trifft zu?",
 o:["Der Mobilfunkvertrag wurde wirksam gekündigt.","Die Kündigung eines Mobilfunkvertrags bedarf immer der Schriftform nach § 126 BGB.","Die Kündigung ist ein einseitiges Rechtsgeschäft mit nicht empfangsbedürftiger Willenserklärung.","Die Kündigung ist mit Leerung des Briefkastens am 1.11. zugegangen, da ab diesem Zeitpunkt die Möglichkeit der Kenntnisnahme bestand.","Eine Kündigung erfordert Abgabe und Zugang der entsprechenden Willenserklärung."],
 a:[0,4],e:"Die Kündigung ging am 31.10. zu: Sie war im Machtbereich des Unternehmens, und während der Geschäftszeit des Tages war mit Kenntnisnahme zu rechnen. § 126 BGB regelt die gesetzliche Schriftform – die ist hier nicht angeordnet. Die Kündigung ist empfangsbedürftig: Abgabe + Zugang nötig."},
{id:"i11",s:"ilias",q:"Welche der folgenden Aussagen ist richtig?",
 o:["Das Abstraktionsprinzip besagt, dass bei einem unwirksamen Kaufvertrag auch immer die Eigentumsübertragung unwirksam ist.","Die Schenkung erfolgt durch einseitiges Rechtsgeschäft.","Die Schenkung erfordert 2 übereinstimmende Willenserklärungen, die beide der notariellen Beurkundung bedürfen.","Die Eigentumsübertragung an einer beweglichen Sache erfolgt entweder durch Kauf-, Tausch- oder Schenkungsvertrag.","Keine der vorgenannten Antworten ist richtig."],
 a:[4],e:"Das Abstraktionsprinzip besagt gerade das Gegenteil. Die Schenkung ist ein Vertrag (§ 516 BGB); formbedürftig ist nur die Erklärung des Schenkers (§ 518). Durch Kauf-, Tausch- oder Schenkungsvertrag verpflichtet man sich nur zur Übereignung – übertragen wird das Eigentum durch Einigung und Übergabe (§ 929)."},
{id:"i12",s:"ilias",q:"Welche der folgenden Antworten bezüglich Rechtsgeschäften trifft zu?",
 o:["Die Willenserklärung des Verkäufers zum Abschluss eines Kaufvertrags nennt man immer Angebot.","Ein Rechtsgeschäft erfordert immer mindestens eine Willenserklärung.","Es gibt Rechtsgeschäfte, die 10 übereinstimmende Willenserklärungen von 10 Personen erfordern.","Die Kündigung eines Mietvertrags ist ein Rechtsgeschäft.","Die Erklärung der Anfechtung nach § 143 ist eine Willenserklärung."],
 a:[1,2,3,4],e:"Das Angebot ist die zeitlich erste auf den Vertragsschluss gerichtete Erklärung – es kann auch vom Käufer kommen. Jedes Rechtsgeschäft enthält mindestens eine Willenserklärung. Ein Gesellschaftsvertrag mit 10 Gesellschaftern braucht 10 Erklärungen. Die Kündigung ist ein einseitiges Rechtsgeschäft; die Anfechtungserklärung ist eine (empfangsbedürftige) Willenserklärung."},
{id:"i13",s:"ilias",q:"Der 90 Jahre alte K, der wegen Altersdemenz geschäftsunfähig ist und unter Betreuung steht, geht am Kiosk des V vorbei und bestellt dort eine Bratwurst. V übergibt K die Bratwurst und K übergibt dem V 2 €, die er von seinem Betreuer als „Taschengeld“ bekommen hat. Was trifft zu?",
 o:["Der Kaufvertrag ist unwirksam, da Geschäftsunfähige niemals wirksam Rechtsgeschäfte abschließen können.","Die Eigentumsübertragung an der Bratwurst ist deswegen wirksam, da dies für den K lediglich rechtlich vorteilhaft ist.","V ist Eigentümer des Geldes geworden.","K ist rechtsunfähig, da er unter Betreuung steht, und kann daher keine wirksamen Rechtsgeschäfte abschließen.","Keine der vorgenannten Antworten ist richtig."],
 a:[2],e:"§ 105a BGB: Ein volljähriger Geschäftsunfähiger kann Geschäfte des täglichen Lebens mit geringwertigen Mitteln wirksam tätigen, sobald Leistung und Gegenleistung bewirkt sind – daher wird V Eigentümer des Geldes. Antwort B ist im Ergebnis richtig, aber falsch begründet (§ 107 gilt nur für Minderjährige). K ist rechtsfähig, aber nicht geschäftsfähig."},
{id:"i14",s:"ilias",q:"Der 8 Jahre alte Tim geht auf dem Heimweg von der Schule am Imbissstand vorbei und bestellt sich ohne Wissen der Eltern eine Portion Pommes. Der Verkäufer übergibt sie ihm und Tim bezahlt den Kaufpreis mit einer 2 €-Münze, die er gerade auf der Straße gefunden hat. Welche der folgenden Antworten ist richtig?",
 o:["Es wurden hier 6 Willenserklärungen abgegeben.","Insgesamt 2 der abgegebenen Willenserklärungen sind (schwebend) unwirksam.","Es liegt ein (schwebend) unwirksames Verpflichtungsgeschäft vor.","Es liegt ein (schwebend) unwirksames Verfügungsgeschäft vor.","Das Verpflichtungsgeschäft ist (schwebend) unwirksam, die beiden Verfügungsgeschäfte aber wegen des Abstraktionsprinzips trotzdem wirksam."],
 a:[0,1,2,3],e:"3 Verträge mit je 2 Willenserklärungen: Kaufvertrag (§ 433), Übereignung der Pommes (§ 929), Übereignung des Geldes. Schwebend unwirksam sind Tims Erklärung zum Kaufvertrag und seine Erklärung zur Übereignung des Geldes (nicht lediglich rechtlich vorteilhaft, keine Zustimmung, kein § 110). Die Übereignung der Pommes an Tim ist lediglich vorteilhaft – wirksam."},

// ===================== Testfragen BGB mit Lösungsspalte =====================
{id:"b001",s:"blatt",q:"Die Brüder Alfred und Arwed Amsel haben gemeinsam ein Auto käuflich erworben, um damit abwechselnd zu fahren. Kaufpreis: 5.000 €; jeder hat 2.500 € gezahlt. Es besteht Bruchteilsgemeinschaft nach §§ 741 ff. BGB. Das Auto war reparaturbedürftig. Die Brüder gaben dem Autohaus Flick KG den Auftrag zur Reparatur. Die Rechnung über 1.000 € ist bisher nicht bezahlt. Ein Rechtsanspruch des Flick besteht:",
 o:["gegen Alfred nur i. H. v. 500 €","gegen beide jeweils nur i. H. v. 500 €","gegen Arwed i. H. v. 1.000 €","gegen jeden von beiden i. H. v. 1.000 €, solange die Rechnung noch offen steht","gegen Alfred i. H. v. 1.000 €"],
 a:[2,3,4],e:"Wer sich gemeinschaftlich vertraglich zu einer teilbaren Leistung verpflichtet, haftet im Zweifel als Gesamtschuldner (§ 427 BGB). Flick kann von jedem die ganze Summe verlangen, insgesamt aber nur einmal (§ 421 BGB)."},
{id:"b002",s:"blatt",q:"Was trifft zu?",
 o:["Das Grundbuch wird am Verwaltungsgericht geführt, da die Eintragungen einen Staatshoheitsakt darstellen.","Das Grundbuch wird vom Rechtspfleger am Amtsgericht geführt.","Das Grundbuch dient der Offenlegung dinglicher Rechte am Grundstück.","Das einzelne Grundbuchblatt wird in 3 Abteilungen gegliedert.","In Abteilung II stehen die Hypotheken und sonstigen Beschränkungen auf dem Grundstück."],
 a:[1,2,3],e:"Grundbuchamt ist das Amtsgericht (§ 1 GBO), zuständig ist i. d. R. der Rechtspfleger. Das Grundbuch macht dingliche Rechte publik. Aufbau: Bestandsverzeichnis + Abteilung I (Eigentümer), II (Lasten und Beschränkungen) und III (Hypotheken, Grund- und Rentenschulden)."},
{id:"b003",s:"blatt",q:"Der rechtsgeschäftliche Eigentumswechsel an einem Grundstück erfordert immer:",
 o:["dass der Erwerber rechtsfähig oder wenigstens teilrechtsfähig ist","dass das Grundstück dem Übertragenden gehört","die Eintragung ins Grundbuch","eine formbedürftige Auflassung","einen Kaufvertrag in der Form des § 311b BGB"],
 a:[0,2,3],e:"§ 873, § 925 BGB: Auflassung (formbedürftig, vor dem Notar) + Eintragung. Erwerben kann nur, wer Rechte haben kann. Dem Übertragenden muss das Grundstück nicht gehören (gutgläubiger Erwerb, § 892). Ein Kaufvertrag ist wegen des Abstraktionsprinzips keine Voraussetzung."},
{id:"b004",s:"blatt",q:"A lässt sich vom Unternehmer U einen Austauschmotor in seinen Wagen einbauen. Bis zur vollständigen Bezahlung behält sich U das Eigentum am Motor vor.",
 o:["Der Motor ist Zubehör des Autos.","Durch den Einbau wurde der Austauschmotor wesentlicher Bestandteil des Autos.","A ist mit Einbau Eigentümer des Motors geworden, weil an wesentlichen Bestandteilen keine selbständigen Rechte bestehen können.","Der Motor ist ein Bestandteil des Autos.","U ist Eigentümer des Motors geblieben."],
 a:[3,4],e:"Ein (Serien-)Austauschmotor kann ohne Zerstörung ausgebaut werden und ist daher nach h. M. kein wesentlicher Bestandteil (§ 93 BGB), sondern einfacher Bestandteil. Deshalb wirkt der Eigentumsvorbehalt: U bleibt Eigentümer. Zubehör (§ 97) ist er nicht, da er Teil der Sache selbst ist."},
{id:"b005",s:"blatt",q:"Welche der folgenden Aussage(n) zu Wertpapieren ist/sind richtig?",
 o:["Die Aktie ist ein Inhaberpapier.","Der Wechsel ist ein Inhaberpapier.","Der Scheck mit Überbringerklausel ist ein Inhaberpapier.","Beim Rektapapier folgt das Recht aus dem Papier dem Recht am Papier.","Beim Rektapapier folgt das Recht am Papier dem Recht aus dem Papier."],
 a:[0,2,4],e:"Die (Inhaber-)Aktie ist ein Inhaberpapier (Namensaktien sind Orderpapiere). Der Wechsel ist ein geborenes Orderpapier. Der Scheck mit Überbringerklausel ist Inhaberpapier. Beim Rektapapier (z. B. Sparbuch) gilt: „Das Recht am Papier folgt dem Recht aus dem Papier“ (§ 952 BGB)."},
{id:"b006",s:"blatt",q:"Ohne Wissen seiner Eltern veräußert der (älter aussehende) 17-jährige Jupp mündlich ein ihm gehörendes Moped für 500 € an den 20-jährigen Heinz, der das wahre Alter von Jupp nicht kennt. Sowohl das Moped als auch das Geld wechseln den Besitzer.",
 o:["Heinz ist Eigentümer des Mopeds geworden – zumindest kraft guten Glaubens.","Jupp ist Eigentümer des Geldes geworden und Eigentümer des Mopeds geblieben.","Der Kaufvertrag ist zunächst schwebend unwirksam.","Der Kaufvertrag kann in Folge Genehmigung durch den gesetzlichen Vertreter Jupps rückwirkend wirksam werden.","Ein Kaufvertrag ist in der mündlichen Abrede nicht zu sehen."],
 a:[1,2,3],e:"Kaufvertrag und Übereignung des Mopeds sind für Jupp rechtlich nachteilig → schwebend unwirksam (§§ 107, 108); die Genehmigung wirkt zurück (§ 184). Der gute Glaube an die Volljährigkeit wird nicht geschützt. Die Übereignung des Geldes an Jupp ist lediglich rechtlich vorteilhaft → wirksam. Ein Kaufvertrag ist formfrei möglich."},
{id:"b007",s:"blatt",q:"Ein wirksames Angebot unter Abwesenden zum Abschluss eines Kaufvertrages setzt voraus:",
 o:["Lediglich die Abgabe der Erklärung","Die Abgabe der Erklärung und den Zugang beim Empfänger","Lediglich den Zugang beim Empfänger","Lediglich die Tatbestandsvoraussetzungen von Willenserklärungen","Eine tatsächliche Kenntnisnahme durch den Erklärungsempfänger ist immer erforderlich."],
 a:[1],e:"Eine empfangsbedürftige Willenserklärung unter Abwesenden wird mit Zugang wirksam (§ 130 Abs. 1 BGB) – sie muss also abgegeben werden und zugehen. Tatsächliche Kenntnisnahme ist nicht nötig."},
{id:"b008",s:"blatt",q:"A bestellt nach eingehendem Studium der Speisekarte eine Gänsekeule mit Beilage zum Preis von 21 €. Kellner W nimmt die Bestellung nickend zur Kenntnis. Welche Aussage(n) ist/sind richtig?",
 o:["Die Bestellung des A ist als Annahme zu werten.","W gibt eine konkludente Willenserklärung ab.","Die Speisekarte stellt ein schriftliches Angebot dar.","Erst mit Servieren des bestellten Gerichts wird ein Vertrag geschlossen.","Mit Kopfnicken des W ist der Bewirtungsvertrag geschlossen."],
 a:[1,4],e:"Die Speisekarte ist nur eine Aufforderung zur Abgabe eines Angebots (invitatio ad offerendum). Die Bestellung ist das Angebot, das Nicken des W die konkludente Annahme – damit ist der Vertrag geschlossen."},
{id:"b009",s:"blatt",q:"Folgende Rechtsgeschäfte sind formbedürftig:",
 o:["Kaufvertrag über ein Auto","Kaufvertrag über ein Grundstück","Schenkungsversprechen","Testament","Bürgschaftserklärung"],
 a:[1,2,3,4],e:"Grundstückskauf: § 311b; Schenkungsversprechen: § 518; Testament: §§ 2231 ff.; Bürgschaftserklärung: § 766 BGB. Der Autokauf ist formfrei."},
{id:"b010",s:"blatt",q:"Welche der nachfolgend aufgeführten Vorgänge sind im Recht der Schuldverhältnisse (2. Buch des BGB) geregelt?",
 o:["V verspricht seinem volljährigen Sohn S, ihm zu dessen nächstem Geburtstag ein Auto zu schenken.","E errichtet sein Testament, indem er seinen Nachbarn X als Alleinerben einsetzt.","Der Unternehmer U zahlt am 15.02.07 die fällige USt i. H. v. 3.000 € nicht.","X verpflichtet sich gegenüber Y, eine Stereoanlage zu übereignen, die Y mit 2.000 € bezahlen will.","H hat auf dem Zebrastreifen den Fußgänger F erfasst und verletzt. Den Schaden beziffert F auf 1.500 €."],
 a:[0,3,4],e:"Schenkungsversprechen (§§ 516, 518), Kaufvertrag (§ 433) und unerlaubte Handlung (§ 823) stehen im 2. Buch. Das Testament gehört zum Erbrecht (5. Buch), die Umsatzsteuer zum Steuerrecht."},
{id:"b011",s:"blatt",q:"Wie kann ein Kaufvertrag qualifiziert werden?",
 o:["Als zweiseitiges Schuldgeschäft","Als Übereignungsvertrag","Als Verpflichtungsgeschäft","Als Erfüllungsgeschäft","Als Schuldvertrag"],
 a:[0,2,4],e:"Der Kaufvertrag ist ein (gegenseitiger) schuldrechtlicher Vertrag, also Verpflichtungsgeschäft. Übereignung und Erfüllung folgen erst als eigene Verfügungsgeschäfte."},
{id:"b012",s:"blatt",q:"Der Zeitungshändler Z schuldet dem Verlag V 20.000 € aus der letzten Bestellung. Z beliefert den Kioskbesitzer K. K verbürgt sich am Telefon gegenüber V für die Schuld des Z. Welche Aussage(n) sind richtig?",
 o:["Die Bürgschaftserklärung per Telefon ist unwirksam.","Bürgschaftserklärungen per Telefon sind immer unwirksam.","K kann seinen Angestellten keine Prokura erteilen.","K kann sich in das bei der Industrie- und Handelskammer geführte Handelsregister eintragen lassen.","K betreibt einen Gewerbebetrieb."],
 a:[0,2,4],e:"Der Kiosk ist ein Gewerbe, aber ein Kleingewerbe – K ist kein Kaufmann (§ 1 Abs. 2 HGB). Daher gilt § 350 HGB (formfreie Bürgschaft des Kaufmanns) nicht, sondern § 766 BGB: telefonisch unwirksam. Für Kaufleute ist eine telefonische Bürgschaft möglich – „immer unwirksam“ stimmt also nicht. Prokura kann nur ein Kaufmann erteilen (§ 48 HGB). Das Handelsregister führt das Amtsgericht, nicht die IHK."},
{id:"b013",s:"blatt",q:"Die Brüder Anton und Benno Buch sind im Betrieb des U angestellt. Anton erhält von U Prokura; versehentlich wird jedoch Benno als Prokurist ins Handelsregister eingetragen und bekannt gemacht. Benno kauft im Namen des U bei H ein. Welche Aussage(n) sind richtig? (Sachverhalt teilweise rekonstruiert)",
 o:["Benno ist mit Eintragung in das Register Prokurist des U.","U ist wegen wirksamer Vertretung durch Benno zur Zahlung des Kaufpreises verpflichtet.","Benno hat nie Prokura erhalten.","U muss zahlen, wenn sich H auf die Eintragung und Bekanntmachung des Benno gem. § 15 HGB beruft.","Keine der vorgegebenen Antworten ist richtig."],
 a:[2,3],e:"Prokura entsteht durch Erteilung (§ 48 HGB), die Eintragung wirkt nur deklaratorisch – Benno ist kein Prokurist. Es liegt also keine wirksame Vertretung vor. Aber: Ist eine Tatsache unrichtig bekannt gemacht, kann sich ein Dritter darauf berufen (§ 15 Abs. 3 HGB) – dann muss U zahlen."},
{id:"b014",s:"blatt",q:"B bestellt für einen Betriebsausflug 40 Mittagessen im Gartenlokal des U. Infolge eines unverschuldeten Unfalls wird der Bus mit den Betriebsangehörigen mehrere Stunden aufgehalten und kann das Lokal nicht mehr rechtzeitig erreichen. Das bereitgestellte Essen verdirbt.",
 o:["U ist verpflichtet, neues Essen zuzubereiten.","U ist nicht verpflichtet, neues Essen zuzubereiten, kann aber auch keine Bezahlung verlangen.","B befindet sich im Annahmeverzug.","B muss das Essen bezahlen, kann aber nicht die Zubereitung neuen Essens verlangen.","U kann Bezahlung nur verlangen, wenn er neues Essen zubereitet."],
 a:[2,3],e:"B hat die angebotene Leistung nicht angenommen – Annahmeverzug (§§ 293 ff.), auf Verschulden kommt es nicht an. Während des Annahmeverzugs trägt B die Gefahr (§ 300 Abs. 2, § 326 Abs. 2 BGB): U wird frei, behält aber den Anspruch auf die Gegenleistung."},
{id:"b015",s:"blatt",q:"Welche der nachstehenden Aussage(n) sind richtig?",
 o:["Bei einer zusammengesetzten Sache liegt, obwohl eine körperliche, zahlenmäßige Mehrheit bestehen kann, eine einheitliche Sache i. S. d. § 90 BGB vor.","Eine Sachgesamtheit besteht aus mehreren Einzelsachen i. S. d. § 90 BGB, wobei an jeder Einzelsache Rechtsbeziehungen, z. B. Eigentumsrechte, bestehen.","Sachgesamtheiten werden steuerlich häufig als ein Wirtschaftsgut behandelt.","Ein Warenlager ist eine Sachgesamtheit, da es Gegenstand eines Kaufvertrages sein kann.","Grundstück, Haus und Außenanlagen werden ertragsteuerlich als Sachgesamtheit angesehen."],
 a:[0,1,2],e:"Zusammengesetzte Sache (z. B. Auto) = eine Sache. Sachgesamtheit (z. B. Bibliothek, Warenlager) = mehrere Sachen, Eigentum besteht an jeder einzelnen (Spezialitätsprinzip). Dass ein Warenlager Kaufgegenstand sein kann, ist nicht der Grund, warum es Sachgesamtheit ist. Grund und Boden, Gebäude und Außenanlagen sind ertragsteuerlich getrennte Wirtschaftsgüter."},
{id:"b016",s:"blatt",q:"A ist Aktionär der X-AG.",
 o:["Die Dividenden sind Nutzungen der Aktien.","Die Dividenden sind mittelbare Früchte der Aktien.","Die Dividenden sind unmittelbare Früchte der Aktien.","Die Aktien gewähren A keine Gebrauchsvorteile.","Die Aktien sind kein Gegenstand einer Lieferung im umsatzsteuerlichen Sinne."],
 a:[0,2],e:"Dividenden sind Erträge, die das Mitgliedschaftsrecht seiner Bestimmung gemäß gewährt – unmittelbare Rechtsfrüchte (§ 99 Abs. 2 BGB) und damit Nutzungen (§ 100 BGB). Mittelbare Früchte (§ 99 Abs. 3) entstehen aus einem Rechtsverhältnis mit Dritten, z. B. Miete. (Lösung laut Lösungsblatt: A und C.)"},
{id:"b017",s:"blatt",q:"Die Abtretung einer Forderung …",
 o:["… ist eine Verfügung.","… kann nur mit Zustimmung des Schuldners erfolgen.","… geschieht durch Vertrag.","… kann immer formfrei erfolgen.","Ein gutgläubiger Erwerb ist grundsätzlich nicht möglich."],
 a:[0,2,4],e:"Die Abtretung ist ein Verfügungsvertrag zwischen Alt- und Neugläubiger (§ 398 BGB); der Schuldner muss nicht zustimmen. Sie ist grundsätzlich formfrei, aber nicht immer (z. B. § 1154 BGB bei Hypothekenforderungen). Mangels Rechtsschein (kein Besitz/Register) gibt es grundsätzlich keinen gutgläubigen Forderungserwerb (Ausnahme § 405)."},
{id:"b018",s:"blatt",q:"Unter Rechtsfähigkeit versteht man die Fähigkeit,",
 o:["Rechte haben zu können","Träger von Rechten und Pflichten zu sein","als natürliche Person Rechte zu haben","als juristische Person Rechte und Pflichten zu haben","Keine der vorgegebenen Antworten ist richtig."],
 a:[1],e:"Rechtsfähigkeit = Fähigkeit, Träger von Rechten UND Pflichten zu sein. Sie gilt für natürliche und juristische Personen gleichermaßen."},
{id:"b019",s:"blatt",q:"Juristische Personen sind",
 o:["Personenvereinigungen und Vermögensmassen, die vom Handelsrecht als selbständige Rechtsperson anerkannt werden","Personenvereinigungen, die von der Bevölkerung als selbständige Rechtssubjekte angesehen werden","Personenvereinigungen und Vermögensmassen, die von der Rechtsordnung als selbständige Rechtsperson anerkannt werden","Personenvereinigungen, die vom Gericht als selbständige Person anerkannt werden","Keine der vorgegebenen Antworten ist richtig."],
 a:[2],e:"Juristische Personen sind Personenvereinigungen (z. B. Verein, GmbH, AG) und Vermögensmassen (Stiftung), denen die Rechtsordnung eigene Rechtsfähigkeit verleiht."},
{id:"b020",s:"blatt",q:"Unter Handlungsfähigkeit wird verstanden:",
 o:["Strafmündigkeit und Straffähigkeit","Fähigkeit, natürliche Handlungen zu begehen","Fähigkeit, mit rechtsverbindlichen Folgen handeln zu können","Fähigkeit, Rechtshandlungen begehen zu können","Deliktsfähigkeit und Geschäftsfähigkeit"],
 a:[2,4],e:"Handlungsfähigkeit ist die Fähigkeit, durch eigenes Handeln Rechtsfolgen herbeizuführen. Sie umfasst Geschäftsfähigkeit (Rechtsgeschäfte) und Deliktsfähigkeit (Verantwortlichkeit für unerlaubte Handlungen)."},
{id:"b021",s:"blatt",q:"Unter Deliktsfähigkeit wird die Fähigkeit verstanden,",
 o:["für unerlaubte Handlungen verantwortlich zu sein","für kriminelles Unrecht zu haften","Gefängnisstrafen auf sich nehmen zu können","Geldstrafen auf sich nehmen zu können","Geld- und Gefängnisstrafen auf sich nehmen zu können"],
 a:[0],e:"Deliktsfähigkeit (§§ 827, 828 BGB) = zivilrechtliche Verantwortlichkeit für unerlaubte Handlungen (Schadensersatz). Strafen sind Strafrecht (Schuldfähigkeit/Strafmündigkeit)."},
{id:"b022",s:"blatt",q:"Bei der Deliktsfähigkeit unterscheidet man die",
 o:["Deliktsunfähigkeit","bedingte Deliktsfähigkeit","volle (unbeschränkte) Deliktsfähigkeit","Deliktsmündigkeit","Deliktsunmündigkeit"],
 a:[0,1,2],e:"Unter 7: deliktsunfähig (§ 828 Abs. 1); 7 bis 17: bedingt deliktsfähig (§ 828 Abs. 2, 3); ab 18: voll deliktsfähig. „Mündigkeit“ ist ein Begriff des Strafrechts."},
{id:"b023",s:"blatt",q:"Bei der Geschäftsfähigkeit unterscheidet das BGB in",
 o:["Geschäftsunfähigkeit","beschränkte Geschäftsfähigkeit","volle Geschäftsfähigkeit","regionale Geschäftsfähigkeit","überregionale Geschäftsfähigkeit"],
 a:[0,1],e:"Laut Lösungsblatt: A und B. Das BGB regelt ausdrücklich nur die Geschäftsunfähigkeit (§ 104) und die beschränkte Geschäftsfähigkeit (§ 106); die volle Geschäftsfähigkeit ist der gesetzlich nicht eigens geregelte Normalfall (ab Volljährigkeit, § 2)."},
{id:"b024",s:"blatt",q:"Die Willenserklärung eines Kindes unter 7 Jahren ist",
 o:["bedingt wirksam","schwebend unwirksam","schwebend wirksam","auf ihren rechtlichen Gehalt auszulegen","unwirksam"],
 a:[4],e:"Kinder unter 7 sind geschäftsunfähig (§ 104 Nr. 1); ihre Willenserklärungen sind nichtig (§ 105 Abs. 1 BGB) – auch eine Genehmigung hilft nicht."},
{id:"b025",s:"blatt",q:"Welche der nachstehenden Aussage(n) ist/sind bezüglich sachenrechtlicher Grundprinzipien richtig?",
 o:["Das Spezialitätsprinzip besagt, dass sich jedes dingliche Recht nur auf eine bestimmte Sache beziehen kann.","Das Publizitätsprinzip besagt, dass für jede am Rechtsleben beteiligte Person die Eigentumsverhältnisse sofort erkennbar sein müssen.","Das Publizitätsprinzip besagt nur, dass die dingliche Rechtslage möglichst offenkundig sein soll.","Das Abstraktionsprinzip besagt, dass der Eigentümer einer Sache jedermann (abstrakt) von der Einwirkung auf sein Eigentum ausschließen kann.","Das Enumerationsprinzip besagt, dass die Sachenrechte abschließend geregelt sind."],
 a:[0,2,4],e:"Spezialität: Rechte nur an bestimmten, einzelnen Sachen. Publizität: Rechtslage soll nach außen erkennbar sein (Besitz, Grundbuch) – „sofort für jeden erkennbar“ ist zu streng. Der Ausschluss Dritter ist das Absolutheitsprinzip, nicht das Abstraktionsprinzip. Typenzwang/Numerus clausus: Sachenrechte sind abschließend geregelt."},
{id:"b026",s:"blatt",q:"Am 01.01.2005 leiht A dem B ein Buch. B verleiht das Buch am 01.02.2005 an C. Am 01.03.2005 wird es dort von D gestohlen. Welche Angabe(n) ist/sind zutreffend?",
 o:["A ist am 25.02.2005 unmittelbarer Besitzer.","A ist am 28.02.2005 mittelbarer Besitzer.","B ist am 05.01.2005 unmittelbarer Eigenbesitzer.","B ist am 28.02.2005 mittelbarer Besitzer.","D ist am 02.03.2005 unmittelbarer Eigenbesitzer."],
 a:[1,3,4],e:"Ab 01.02. hat C den unmittelbaren Besitz; B ist mittelbarer Besitzer (§ 868), A mittelbarer Besitzer 2. Stufe (§ 871). Im Januar ist B unmittelbarer Fremdbesitzer (er besitzt für A). Der Dieb D besitzt unmittelbar und als ob ihm die Sache gehöre – Eigenbesitzer (§ 872)."},
{id:"b027",s:"blatt",q:"Welche Form des Besitzes erkennen Sie in der Person eines angestellten Kellners (K) in einer Gaststätte?",
 o:["K hat unmittelbaren Besitz an den Bestecken, Tellern, Platten etc., die er gerade serviert.","K hat nur mittelbaren Besitz an den dem Gast bereits vorgelegten Gegenständen.","K ist Besitzdiener und hat daher keinerlei Besitz an den in der Gaststätte zur Bedienung des Gastes verwendeten Gegenständen.","K hat unmittelbaren Besitz an eigenem Barvermögen, welches er bei sich trägt.","K hat auch unmittelbaren Besitz an dem ihm vom Gastwirt zur Verfügung gestellten Wechselgeld."],
 a:[2,3],e:"Der Kellner übt die Sachherrschaft für den Wirt nach dessen Weisungen aus – Besitzdiener (§ 855 BGB); Besitzer ist allein der Wirt. Das gilt auch für das Wechselgeld des Wirts. An seinem eigenen Geld hat K natürlich unmittelbaren Besitz."},
{id:"b028",s:"blatt",q:"Bei der Sicherungsübereignung wird/werden i. d. R. folgende Rechtsposition(en) eingenommen: Der Sicherungsgeber …",
 o:["… verändert seine Besitzposition hinsichtlich der tatsächlichen Sachherrschaft.","… behält unmittelbaren Besitz.","… verliert sein Eigentum in vollem Umfang.","… bleibt nach h. M. Eigenbesitzer, weil er davon ausgeht, dass er schuldrechtlich noch Eigentum hat.","… erhält mittelbaren Besitz."],
 a:[1,2],e:"Sicherungsübereignung nach § 930 BGB: Der Sicherungsgeber behält die Sache (unmittelbarer Fremdbesitzer), der Sicherungsnehmer wird Eigentümer und mittelbarer Besitzer. Dinglich verliert der Sicherungsgeber das Eigentum vollständig; er hat nur schuldrechtliche Rückübertragungsansprüche."},
{id:"b029",s:"blatt",q:"Der Besitz hat u. a. folgende Bedeutung und Funktion:",
 o:["Eigentumsvermutung","Bedeutung für den gutgläubigen Erwerb von Eigentum an beweglichen Sachen","Keine Bedeutung für den gutgläubigen Erwerb von Eigentum an beweglichen Sachen","Publizitätsfunktion","Beweisfunktion, dass der unmittelbare Besitzer zugleich der Eigentümer der Sache ist"],
 a:[0,1,3],e:"§ 1006 BGB: Zugunsten des Besitzers wird vermutet, dass er Eigentümer ist (Vermutung, kein Beweis). Der Besitz ist Rechtsscheinträger für den gutgläubigen Erwerb (§§ 932 ff.) und macht die dingliche Lage nach außen erkennbar (Publizität)."},
{id:"b030",s:"blatt",q:"Ein rechtsgeschäftlicher Eigentumserwerb an beweglichen Sachen setzt immer voraus, dass …",
 o:["… die Sache demjenigen gehört, der die Einigung und Übergabe vollzieht.","… zwischen den Beteiligten ein wirksamer Kaufvertrag vorliegt.","… eine wirksame dingliche Einigung über den Eigentumswechsel zwischen den Vertragsparteien vorliegt.","… der Erwerber unmittelbaren Besitz an der Sache erhält.","… der Erwerber und der Veräußerer rechtsfähig bzw. teilrechtsfähig sind."],
 a:[2],e:"Laut Lösungsblatt nur C: Die dingliche Einigung ist bei allen Erwerbstatbeständen (§§ 929–931) erforderlich. Nicht immer nötig: Eigentum des Veräußerers (gutgläubiger Erwerb), ein Kaufvertrag (Abstraktionsprinzip) oder unmittelbarer Besitz (§§ 930, 931)."},
{id:"b031",s:"blatt",q:"Welche der nachstehenden Aussage(n) ist/sind richtig?",
 o:["Der gesetzliche Güterstand ist die allgemeine Gütergemeinschaft.","Der gesetzliche Güterstand ist die Gütertrennung.","Die Zugewinngemeinschaft ist ein vertraglicher Güterstand.","Die Zugewinngemeinschaft ist eine Gütergemeinschaft mit Zugewinnausgleich.","Die Zugewinngemeinschaft ist eine Gütertrennung mit Zugewinnausgleich."],
 a:[4],e:"Gesetzlicher Güterstand ist die Zugewinngemeinschaft (§ 1363 BGB): Die Vermögen bleiben getrennt (§ 1363 Abs. 2), am Ende wird der Zugewinn ausgeglichen. Gütertrennung und Gütergemeinschaft sind vertragliche Güterstände."},
{id:"b032",s:"blatt",q:"Der Zugewinnausgleich erfolgt",
 o:["bei Beendigung der Ehe","durch Tod des Ehegatten","bei Beendigung des gesetzlichen Güterstandes durch Tod eines Ehegatten","bei Beendigung des gesetzlichen Güterstandes durch Scheidung der Ehe","jederzeit auf Wunsch eines Ehegatten"],
 a:[2,3],e:"Ausgeglichen wird bei Beendigung des Güterstandes: durch Tod (§ 1371 – pauschal über den erhöhten Erbteil) oder auf andere Weise, z. B. Scheidung (§§ 1372 ff.)."},
{id:"b033",s:"blatt",q:"An den Antrag (das Angebot) ist man",
 o:["24 Stunden gebunden","auf ewig gebunden","überhaupt nicht gebunden","ca. 14 Tage gebunden","Keine der vorgegebenen Antworten ist richtig."],
 a:[4],e:"Gebunden ist man, bis der Antrag erlischt (§ 145 BGB): unter Anwesenden nur sofort (§ 147 Abs. 1), unter Abwesenden bis zu dem Zeitpunkt, in dem man eine Antwort unter regelmäßigen Umständen erwarten darf (§ 147 Abs. 2), oder bis zur gesetzten Frist (§ 148). Feste Fristen gibt es nicht."},
{id:"b034",s:"blatt",q:"Ein Kaufvertrag verschafft dem Käufer",
 o:["das Eigentum an der Kaufsache","nicht das Eigentum an der Kaufsache","einen Anspruch auf Übereignung","einen Anspruch auf Abschluss eines Übereignungsvertrages","Keine der vorgegebenen Antworten ist richtig."],
 a:[1,2,3],e:"Der Kaufvertrag verpflichtet nur (§ 433 Abs. 1 BGB): Der Käufer erhält einen Anspruch auf Übergabe und Übereignung – also auf Abschluss der dinglichen Einigung. Eigentum erhält er erst durch die Übereignung."},
{id:"b035",s:"blatt",q:"Mieter A möchte seine Wohnung zum nächstmöglichen Termin kündigen. Vermieter B, der die fristgerechte Kündigung verhindern will, wirft den verschlossenen Briefumschlag, in dem er zu Recht das Kündigungsschreiben des A vermutet, in den Papierkorb. Welche Aussage(n) ist/sind richtig?",
 o:["Die Kündigung ist nicht zugegangen.","Die Kündigung ist eine nicht empfangsbedürftige Willenserklärung.","Die Kündigung ist wirksam geworden.","Die Kündigung ist ein einseitiges Rechtsgeschäft.","Die Kündigung ist ein Vertrag."],
 a:[2,3],e:"Der Brief war in B's Machtbereich, B hatte die Möglichkeit der Kenntnisnahme – zugegangen. Wer den Zugang treuwidrig vereitelt, kann sich ohnehin nicht darauf berufen (§ 242 BGB). Die Kündigung ist ein einseitiges Rechtsgeschäft mit empfangsbedürftiger Willenserklärung."},
{id:"b036",s:"blatt",q:"A legt ein 2-€-Stück auf die Verkaufstheke des Zeitschriftenhändlers B und nimmt sich den „Spiegel“; B nickt. Wie viele Rechtsgeschäfte und Willenserklärungen liegen vor? (Sachverhalt teilweise rekonstruiert)",
 o:["Ein Rechtsgeschäft","Zwei Willenserklärungen","Zwei Rechtsgeschäfte","Drei Rechtsgeschäfte","Sechs Willenserklärungen"],
 a:[3,4],e:"Kaufvertrag + Übereignung der Zeitschrift + Übereignung des Geldes = 3 Rechtsgeschäfte, jeweils mit 2 (konkludenten) Willenserklärungen = 6 Willenserklärungen."},
{id:"b037",s:"blatt",q:"Es gibt",
 o:["schuldrechtliche Verträge","sachenrechtliche Verträge","familienrechtliche Verträge","Verpflichtungsgeschäfte","Verfügungsgeschäfte"],
 a:[0,1,2,3,4],e:"Alle genannten gibt es: z. B. Kaufvertrag (schuldrechtlich, Verpflichtung), Übereignung (sachenrechtlich, Verfügung), Ehevertrag (familienrechtlich)."},
{id:"b038",s:"blatt",q:"Sachen sind",
 o:["körperliche und immaterielle Gegenstände","Gegenstände und Rechte","nur körperliche Gegenstände","weder Gegenstände noch Rechte","Keine der vorgegebenen Antworten ist richtig."],
 a:[2],e:"§ 90 BGB: Sachen sind nur körperliche Gegenstände. Rechte sind Gegenstände, aber keine Sachen."},
{id:"b039",s:"blatt",q:"Der in ein Auto eingebaute Serienmotor",
 o:["ist nicht dessen wesentlicher Bestandteil","kann ausnahmsweise einem anderen Eigentümer als dem Eigentümer des restlichen Autos gehören","kann ausgebaut werden, ohne dass dies zur Vernichtung wirtschaftlicher Werte führt","ist Scheinbestandteil des Autos","ist wesentlicher Bestandteil des Autos, weil er das Wesen des Autos ausmacht"],
 a:[0,1,2],e:"Nach BGH ist ein Serienmotor kein wesentlicher Bestandteil (§ 93 BGB), weil er ohne Zerstörung oder Wesensänderung ausgebaut und ersetzt werden kann. Deshalb kann an ihm gesondertes Eigentum bestehen (z. B. Eigentumsvorbehalt). Ein Scheinbestandteil (§ 95) ist er nicht."},
{id:"b040",s:"blatt",q:"A vermietet seinen Pkw an B. Der B überlässt den Pkw unentgeltlich an C. Welche der folgenden Aussage(n) ist/sind zutreffend?",
 o:["A ist kein unmittelbarer Besitzer mehr.","A ist Eigentümer.","B ist unmittelbarer Besitzer.","B ist mittelbarer Besitzer.","C ist mittelbarer Besitzer."],
 a:[0,1,3],e:"C hat die tatsächliche Sachherrschaft – unmittelbarer Besitzer. B (Leihe an C) ist mittelbarer Besitzer 1. Stufe, A (Miete an B) mittelbarer Besitzer 2. Stufe (§ 871) und weiterhin Eigentümer."},
{id:"b041",s:"blatt",q:"X hat vom Hausmeister J eine Wohnung gemietet. Welche der folgenden Aussage(n) ist/sind zutreffend?",
 o:["X ist mittelbarer Besitzer der Wohnung.","J ist unmittelbarer Besitzer der Wohnung.","X ist Besitzer der Wohnung.","X ist weder Besitzer noch Eigentümer der Wohnung.","J ist mittelbarer Besitzer der Wohnung."],
 a:[2,4],e:"Der Mieter X übt die tatsächliche Sachherrschaft aus – unmittelbarer Besitzer. J ist als Vermieter mittelbarer Besitzer (§ 868 BGB)."},
{id:"b042",s:"blatt",q:"A hat eine dem B gehörende Wohnung von B gemietet. B besetzt ohne Erlaubnis des A die Wohnung. Welche der folgenden Aussage(n) ist/sind zutreffend?",
 o:["A kann den B mit Gewalt aus der Wohnung entfernen.","A muss den Aufenthalt von B dulden.","A kann den B als Eigentümer nur bitten, die Wohnung zu verlassen.","A kann den B schlimmstenfalls erschießen.","Keine der vorgegebenen Antworten ist richtig."],
 a:[0],e:"Auch der Eigentümer begeht gegenüber dem Besitzer verbotene Eigenmacht (§ 858 BGB). A darf sich durch Besitzwehr/Besitzkehr mit (angemessener) Gewalt wehren (§ 859 BGB). Erschießen wäre völlig unverhältnismäßig."},
{id:"b043",s:"blatt",q:"Rechtsgeschäftlicher Eigentumserwerb an einer beweglichen Sache erfolgt durch",
 o:["Abschluss eines Kaufvertrages","Ersitzung","Aneignung","Einigung und Übergabe","Einigung und Abtretung des Herausgabeanspruchs"],
 a:[3,4],e:"Rechtsgeschäftlich: §§ 929 (Einigung + Übergabe), 930 (Besitzkonstitut), 931 (Abtretung des Herausgabeanspruchs). Ersitzung (§ 937) und Aneignung (§ 958) sind gesetzliche Erwerbstatbestände; der Kaufvertrag verpflichtet nur."},
{id:"b044",s:"blatt",q:"A hat ein unbebautes Grundstück für 10 Jahre gepachtet. Er hat die Erlaubnis erhalten, hierauf ein fest mit dem Grund und Boden verbundenes Wochenendhaus zu errichten. Nach Ablauf der Pachtzeit muss er das Grundstück „wie gepachtet“ zurückgeben. Das Wochenendhaus ist",
 o:["wesentlicher Bestandteil des Grund und Bodens","Scheinbestandteil","Zubehör","bewegliche Sache","unbewegliche Sache"],
 a:[1,3],e:"Es wurde nur zu einem vorübergehenden Zweck (Pachtdauer) mit dem Boden verbunden – Scheinbestandteil (§ 95 Abs. 1 BGB). Scheinbestandteile werden rechtlich als bewegliche Sachen behandelt; A bleibt Eigentümer."},
{id:"b045",s:"blatt",q:"A schließt am 08.09.07 mit B einen Kaufvertrag über seinen gebrauchten Pkw ab. Welche der folgenden Aussage(n) ist/sind zutreffend?",
 o:["B wird am 08.09.07 Eigentümer.","A ist ab dem 08.09.07 verpflichtet, dem B Eigentum zu verschaffen.","B wird am 08.09.07 Besitzer.","A bleibt bis zur Eigentumsverschaffung Besitzer.","A bleibt bis zur Eigentumsverschaffung Eigentümer."],
 a:[1,3,4],e:"Der Kaufvertrag begründet nur die Pflicht zur Übergabe und Übereignung (§ 433 Abs. 1). Besitz und Eigentum bleiben bis zur Erfüllung (§ 929) bei A."},
{id:"b046",s:"blatt",q:"Der Eigentümer",
 o:["unterliegt der Sozialbindung des Eigentums","ist stets auch unmittelbarer Besitzer der Sache","kann ohne Rücksicht auf Rechte anderer mit seiner Sache nach Belieben verfahren","hat das umfassende Herrschaftsrecht an seiner Sache","kann verpflichtet sein, Beeinträchtigungen durch Dritte zu dulden"],
 a:[0,3,4],e:"Art. 14 Abs. 2 GG: Eigentum verpflichtet. Eigentum ist das umfassende Herrschaftsrecht (§ 903 BGB) – aber nur, „soweit nicht das Gesetz oder Rechte Dritter entgegenstehen“; Duldungspflichten z. B. § 906 BGB. Eigentum und Besitz fallen oft auseinander (Miete)."},
{id:"b047",s:"blatt",q:"Eine Hypothek",
 o:["ist eine Belastung von Grundeigentum","kommt nur dann zustande, wenn sie im Grundbuch eingetragen ist","kann unabhängig von einer Forderung bestellt werden","kann nur für eine bereits bestehende Forderung bestellt werden","verliert ihre Bedeutung, wenn die Forderung untergegangen ist"],
 a:[0,1,4],e:"Die Hypothek belastet ein Grundstück (§ 1113), entsteht durch Einigung und Eintragung (§ 873) und ist akzessorisch: ohne Forderung keine Hypothek (§ 1163 – sie wird dann zur Eigentümergrundschuld). ACHTUNG – Abweichung vom Lösungsblatt: Dort ist auch D angekreuzt; nach § 1113 Abs. 2 BGB kann eine Hypothek aber auch für eine künftige oder bedingte Forderung bestellt werden, daher ist D hier falsch."},
{id:"b048",s:"blatt",q:"Ein Pfandrecht an einer beweglichen Sache kann entstehen",
 o:["durch Einigung","durch Einigung und Übergabe der Sache an den Pfandgläubiger","durch Einigung und Übergabe der Sache und Eintragung in ein Pfandregister","durch Erfüllung eines gesetzlichen Tatbestands","durch staatlichen Hoheitsakt"],
 a:[1,3,4],e:"Vertraglich: Einigung + Übergabe (§ 1205 BGB) – Einigung allein reicht nicht (Faustpfandprinzip). Gesetzlich: z. B. Vermieterpfandrecht (§ 562). Hoheitlich: Pfändungspfandrecht in der Zwangsvollstreckung (§ 804 ZPO). Ein Pfandregister gibt es für bewegliche Sachen nicht. ACHTUNG – Abweichung vom Lösungsblatt: Dort ist auch A angekreuzt."},
{id:"b049",s:"blatt",q:"Die Vereinbarung von Sicherungseigentum an einer beweglichen Sache unterscheidet sich von der Bestellung eines Pfandrechts dadurch, dass",
 o:["der alte Eigentümer unmittelbarer Besitzer bleibt","der neue Eigentümer mittelbarer Besitzer wird","der alte Eigentümer mittelbarer Besitzer wird","der neue Eigentümer unmittelbarer Besitzer wird","der neue Eigentümer dem alten Eigentümer den unmittelbaren Besitz nach Erlöschen der gesicherten Forderung nicht mehr einzuräumen braucht"],
 a:[0,1,4],e:"Bei der Sicherungsübereignung (§ 930) bleibt der Sicherungsgeber im unmittelbaren Besitz, der Sicherungsnehmer wird mittelbarer Besitzer. Beim Pfandrecht muss die Sache dagegen übergeben werden (§ 1205) und nach Erlöschen der Forderung zurückgegeben werden (§ 1223) – beim Sicherungseigentum hat der Geber den Besitz ja schon."},
{id:"b050",s:"blatt",q:"Welche der nachstehenden Aussage(n) ist/sind richtig?",
 o:["Die Ehemündigkeit ist in jedem Fall mit der Vollendung des 16. Lebensjahres gegeben.","Eine gültige Ehe kann nur vor einem Standesbeamten geschlossen werden.","Die Verlobten können sich vor dem Standesbeamten bei Eingehung der Ehe vertreten lassen.","Der Ehename ist der des Mannes.","Ein Verlöbnis ist ein normaler zweiseitiger Vertrag."],
 a:[1,4],e:"Ehemündig ist man mit 18 (§ 1303 BGB). Die Ehe wird vor dem Standesbeamten geschlossen (§ 1310), persönlich und bei gleichzeitiger Anwesenheit (§ 1311) – Vertretung ausgeschlossen. Ehename: frei wählbar (§ 1355). Das Verlöbnis ist nach h. M. ein Vertrag (Lösungsblatt: richtig) – aus ihm kann allerdings nicht auf Eingehung der Ehe geklagt werden (§ 1297)."},
{id:"b051",s:"blatt",q:"Die Willenserklärung eines 14-Jährigen ist",
 o:["generell unwirksam","generell wirksam","schwebend unwirksam","unwirksam, bis die gesetzliche Vertretung sie genehmigt","Keine der vorgegebenen Antworten ist richtig."],
 a:[2],e:"Ein 14-Jähriger ist beschränkt geschäftsfähig (§ 106). Ein ohne Einwilligung geschlossener, nicht lediglich vorteilhafter Vertrag ist schwebend unwirksam (§ 108 BGB) – die Genehmigung wirkt dann zurück."},
{id:"b052",s:"blatt",q:"17-jährige Jugendliche können",
 o:["generell wirksame Willenserklärungen abgeben","unter gewissen Umständen wirksame Willenserklärungen abgeben","keine wirksamen Willenserklärungen abgeben","nur schwebend unwirksame Willenserklärungen abgeben","Keine der vorgegebenen Antworten ist richtig."],
 a:[1],e:"Beschränkt Geschäftsfähige handeln wirksam bei lediglich rechtlichem Vorteil (§ 107), mit Einwilligung, nach § 110 (Taschengeld) oder §§ 112, 113."},
{id:"b053",s:"blatt",q:"Der Taschengeldparagraph befähigt Kinder unter 7 Jahren,",
 o:["generell wirksame Willenserklärungen abgeben zu können","nur manchmal wirksame Willenserklärungen abgeben zu können","nicht, wirksame Willenserklärungen abgeben zu können","für sie günstige Willenserklärungen wirksam abzugeben","Keine der vorgegebenen Antworten ist richtig."],
 a:[2],e:"§ 110 BGB gilt nur für beschränkt Geschäftsfähige (7–17). Kinder unter 7 sind geschäftsunfähig – ihre Erklärungen sind immer nichtig (§ 105)."},
{id:"b054",s:"blatt",q:"Paragraph 110 BGB befähigt 17-Jährige,",
 o:["sich Sachen zu kaufen","wirksame Willenserklärungen abzugeben, soweit sie die rechtlichen Verbindlichkeiten dieser Erklärung mit Mitteln begleichen, die ihnen vom gesetzlichen Vertreter zur Befriedigung ihrer persönlichen Bedürfnisse überlassen worden sind","im Rahmen der Genehmigung des gesetzlichen Vertreters wirksam Willenserklärungen abgeben zu können, wenn die vertragliche Leistung seitens des Jugendlichen mit Mitteln bewirkt wird, die ihm zur Verfügung stehen","Ratenkaufverträge abschließen zu können","Keine der vorgegebenen Antworten ist richtig."],
 a:[1],e:"§ 110: Der Vertrag gilt als von Anfang an wirksam, wenn der Minderjährige die Leistung mit Mitteln bewirkt, die ihm zu diesem Zweck oder zur freien Verfügung überlassen wurden. Ratenkäufe sind gerade nicht erfasst – die Leistung muss vollständig bewirkt sein."},
{id:"b055",s:"blatt",q:"Unter partieller Geschäftsfähigkeit versteht man die Fähigkeit,",
 o:["im Rahmen des § 110 BGB Willenserklärungen abgeben zu können","in bestimmten Lebensbereichen als Jugendlicher voll gültige Willenserklärungen abgeben zu können","unter gewissen Voraussetzungen in bestimmten Lebensbereichen als Jugendlicher voll gültige Willenserklärungen abgeben zu können","als Lehrling Willenserklärungen abgeben zu können","Keine der vorgegebenen Antworten ist richtig."],
 a:[2],e:"Partielle (Teil-)Geschäftsfähigkeit: §§ 112 (selbständiges Erwerbsgeschäft mit Ermächtigung + Genehmigung des Familiengerichts) und 113 (Dienst-/Arbeitsverhältnis mit Ermächtigung) – also nur unter bestimmten Voraussetzungen."},
{id:"b056",s:"blatt",q:"Unter einer Willenserklärung versteht man",
 o:["die Äußerung eines bestimmten Willens","die Äußerung eines natürlichen Willens","die Äußerung eines Willens, die auf die Herbeiführung eines Rechtserfolges gerichtet ist","die Äußerung eines Willens, die auf die Begründung einer Verbindlichkeit gerichtet ist","die Äußerung eines Willens, die auf die Begründung eines Rechts gerichtet ist"],
 a:[2],e:"Willenserklärung = Äußerung eines Willens, der unmittelbar auf die Herbeiführung einer Rechtsfolge gerichtet ist. Verbindlichkeit oder Recht zu begründen sind nur einzelne mögliche Rechtsfolgen (auch Aufheben, Ändern, Übertragen gehört dazu)."},
{id:"b057",s:"blatt",q:"Eine Willenserklärung kann abgegeben werden",
 o:["ausdrücklich","durch schlüssiges Verhalten","durch generelles Schweigen","durch Kopfnicken","durch Kopfschütteln"],
 a:[0,1,3,4],e:"Ausdrücklich oder konkludent (schlüssig), z. B. durch Nicken (Zustimmung) oder Kopfschütteln (Ablehnung). Schweigen ist grundsätzlich keine Willenserklärung (Ausnahmen: § 362 HGB, kaufmännisches Bestätigungsschreiben)."},
{id:"b058",s:"blatt",q:"Ein rechtsgeschäftlicher Eigentumserwerb an beweglichen Sachen setzt immer voraus, dass",
 o:["die Sache dem Übertragenden gehört","zwischen den Beteiligten ein wirksamer Kaufvertrag vorliegt","eine wirksame dingliche Einigung über den Eigentumserwerb zwischen den Beteiligten vorliegt","der Erwerber mittelbaren Besitz an der Sache erhält","der Erwerber voll geschäftsfähig ist"],
 a:[2],e:"Immer nötig ist die dingliche Einigung (§§ 929–931). Gutgläubiger Erwerb vom Nichtberechtigten ist möglich, ein Kaufvertrag ist wegen des Abstraktionsprinzips keine Voraussetzung, und auch ein Minderjähriger kann Eigentum erwerben (lediglich rechtlich vorteilhaft, § 107)."},
{id:"b059",s:"blatt",q:"Welche der folgenden Aussage(n) ist/sind zutreffend? Der rechtsgeschäftliche Eigentumswechsel an einem Grundstück bedarf immer",
 o:["der Eintragung ins Grundbuch","einer Einigung zwischen dem Übertragenden und dem Erwerber","Die Eintragung ins Grundbuch wird als Auflassung bezeichnet.","Die Auflassung ist formbedürftig.","Der Kaufvertrag über ein Grundstück wird als Auflassung bezeichnet."],
 a:[0,1,3],e:"§§ 873, 925 BGB: Einigung (= Auflassung, bei gleichzeitiger Anwesenheit vor dem Notar) + Eintragung. Die Auflassung ist die dingliche Einigung – weder die Eintragung noch der Kaufvertrag."},
{id:"b060",s:"blatt",q:"Der Eigentümer E leiht dem A ein Fahrrad. A verleiht das Fahrrad weiter an B und dieser weiter an C. C möchte das Fahrrad erwerben. Er weiß, dass A das Fahrrad an B verliehen hat, und hält A für den Eigentümer. C und A einigen sich über den Eigentumsübergang.",
 o:["E ist Eigentümer des Fahrrades geblieben.","C ist Eigentümer des Fahrrades geworden.","Die Einigung zwischen C und A ist unwirksam, da A nicht Eigentümer des Fahrrades war.","Ein gutgläubiger Erwerb des Fahrrades durch C scheitert an § 935 (1) BGB.","Ein Nichteigentümer kann niemals einem anderen wirksam Eigentum verschaffen."],
 a:[1],e:"C hat das Fahrrad schon in Händen – es genügt die Einigung (§ 929 S. 2 BGB); die Besitzkette führt über B auf A zurück. C ist gutgläubig (§ 932). Das Rad ist nicht abhanden gekommen, denn E hat es freiwillig verliehen – § 935 greift nicht. Also wird C Eigentümer. (Die Lösung in einer der beiden Kopien kreuzt A an, die andere B – hier gilt B.)"},
{id:"b061",s:"blatt",q:"Welche der folgenden Rechtsgeschäfte sind Verfügungsgeschäfte?",
 o:["A übereignet B durch Einigung und Übergabe gem. § 929 S. 1 BGB ein Radio.","A kauft bei einem Autohändler ein neues Auto. Die Lieferung soll in ca. 4 Wochen erfolgen.","A und B schließen einen Mietvertrag (§ 535 BGB).","A und B schließen einen Tauschvertrag (§ 515 BGB); danach soll A von B ein Radiogerät und B von A einen Plattenspieler erhalten.","Der Sicherungsgeber übereignet das Sicherungsgut gem. § 930 BGB an den Sicherungsnehmer."],
 a:[0,4],e:"Übereignungen (§ 929, § 930) sind Verfügungen. Kauf, Miete und Tausch begründen nur Pflichten."},
{id:"b062",s:"blatt",q:"Folgende Rechtshandlungen können grds. nicht unter einer echten Bedingung vorgenommen werden:",
 o:["Auflassung","Kaufvertrag über Grundstücke","einseitig gestaltende Rechtsgeschäfte","Aufrechnung","Eigentumsübertragung an beweglichen Sachen"],
 a:[0,2,3],e:"Bedingungsfeindlich: Auflassung (§ 925 Abs. 2), Aufrechnung (§ 388 S. 2) und grundsätzlich alle Gestaltungsrechte wie Kündigung oder Anfechtung (Rechtssicherheit für den Empfänger). Bewegliche Sachen können aufschiebend bedingt übereignet werden (Eigentumsvorbehalt, § 449)."},
{id:"b063",s:"blatt",q:"Die Tante T der Studentin S stellt folgende Bereicherung in Aussicht: „Wenn du deine Prüfung tatsächlich bestehen solltest, werde ich dir mein Silberarmband schenken.“",
 o:["Die Erklärung der T ist ein empfangsbedürftiges Angebot zum Abschluss eines Schenkungsversprechens.","Die Erklärung enthält eine Bedingung.","Die Erklärung enthält eine aufschiebende Bedingung.","Die Erklärung der T bedarf der Annahme der S.","Die Erklärung der T ist nicht wirksam, solange die Prüfung nicht bestanden ist."],
 a:[0,1,2,3],e:"Das Bestehen ist ein ungewisses künftiges Ereignis – aufschiebende Bedingung (§ 158 Abs. 1). Die Schenkung ist ein Vertrag, also braucht es die Annahme. Die Erklärung selbst ist sofort wirksam; nur die Rechtswirkung hängt von der Bedingung ab. (Formhinweis: § 518 BGB.)"},
{id:"b064",s:"blatt",q:"Das Finanzamt ist Gläubiger einer USt-Forderung gegen S. Hilfreich, der Freund des S, sagt zu diesem (S): „Das Geld zahle ich für dich, aber mit dem Finanzamt will ich nichts zu tun haben, soll nichts davon wissen.“ Wie beurteilen Sie die Erklärung des Hilfreich?",
 o:["Sie ist rechtlich bedeutungslos.","Sie ist ein Angebot zum Schuldbeitritt.","Sie ist ein Angebot zur befreienden Schuldübernahme.","Sie ist ein Angebot zu einem Erfüllungsübernahmevertrag.","Sie ist ein Angebot zu einem Vertrag zugunsten Dritter."],
 a:[3],e:"Hilfreich will sich nur gegenüber S verpflichten, dessen Schuld zu bezahlen; das Finanzamt soll kein eigenes Forderungsrecht gegen ihn erhalten – Erfüllungsübernahme (§ 329 BGB). Schuldbeitritt und Schuldübernahme würden eine Haftung gegenüber dem Gläubiger begründen."},
{id:"b065",s:"blatt",q:"Der Gläubiger einer Leistung hat bei Schuldnermehrheit (Gesamtschuld) folgende Rechte:",
 o:["Der Gläubiger kann von jedem Gesamtschuldner die Leistung verlangen.","Der Gläubiger kann von jedem Gesamtschuldner die Leistung in vollem Umfang verlangen.","Der Gläubiger kann von den Gesamtschuldnern nur gemeinschaftliche Leistung verlangen.","Der Gläubiger kann von jedem Gesamtschuldner nur anteilige Leistung verlangen.","Der Gläubiger hat gegenüber jedem Gesamtschuldner immer die gleiche rechtliche Stellung (vgl. § 425 BGB)."],
 a:[0,1],e:"§ 421 BGB: Der Gläubiger kann die Leistung nach Belieben von jedem ganz oder teilweise fordern, insgesamt aber nur einmal. § 425: Bestimmte Tatsachen (z. B. Verzug, Verjährung) wirken nur für und gegen den jeweiligen Schuldner – die Stellung ist also nicht immer gleich."},
{id:"b066",s:"blatt",q:"A geht am 19.05. in die Bücherei B, um den Bestseller „Das bluttriefende Hemd“ zu kaufen. Am 29.05. erhält A das Buch gegen Bezahlung von 28 € ausgehändigt. Welche Aussage(n) sind richtig?",
 o:["Ein Kaufvertrag ist am 19.05. nicht zustande gekommen, da hier nur eine mündliche Vereinbarung getroffen wurde.","Der Kaufvertrag ist erst am 29.05. mit der Zahlung des Kaufpreises zustande gekommen.","Die Zahlung des Kaufpreises ist ein Teil des Verpflichtungsgeschäfts.","Der Kaufvertrag ist am 19.05. zustande gekommen.","Keine der vorgegebenen Antworten ist richtig."],
 a:[3],e:"Der Kaufvertrag ist formfrei und kam am 19.05. zustande. Die Zahlung ist ein eigenes Verfügungsgeschäft (Übereignung des Geldes) zur Erfüllung."},
{id:"b067",s:"blatt",q:"Bauer A borgt sich bei seinem Nachbarn B 10 Zentner Kunstdünger, die er noch am selben Tag auf seinen Feldern ausbringt. Welches Rechtsgeschäft haben A und B abgeschlossen? (Sachverhalt teilweise rekonstruiert)",
 o:["Leihvertrag","Tauschvertrag","Kaufvertrag","Darlehensvertrag","Kein Rechtsgeschäft"],
 a:[3],e:"Der Dünger wird verbraucht; A muss Sachen gleicher Art, Güte und Menge zurückgeben – Sachdarlehen (§ 607 BGB). Bei der Leihe (§ 598) wäre dieselbe Sache zurückzugeben."},
{id:"b068",s:"blatt",q:"Der Vertreter",
 o:["gibt eine eigene Willenserklärung ab","gibt eine fremde Willenserklärung ab","handelt im eigenen Namen für fremde Rechnung","handelt im fremden Namen","muss die Vertretung nach § 164 (1) BGB grundsätzlich offenkundig machen"],
 a:[0,3,4],e:"Der Vertreter gibt eine eigene Willenserklärung im fremden Namen ab (§ 164 Abs. 1 BGB, Offenkundigkeitsprinzip). Wer eine fremde Erklärung nur überbringt, ist Bote. Im eigenen Namen für fremde Rechnung handelt z. B. der Kommissionär (mittelbare Stellvertretung)."},
{id:"b069",s:"blatt",q:"Die Eintragung ins Handelsregister",
 o:["einer Prokura ist konstitutiv","eines Istkaufmanns ist deklaratorisch","eines Kannkaufmanns ist nach Wahl des Kaufmanns möglich","eines Kannkaufmanns ist deklaratorisch","einer GmbH ist konstitutiv"],
 a:[1,2,4],e:"Prokura entsteht mit Erteilung (Eintragung nur deklaratorisch, § 53 HGB). Istkaufmann (§ 1 HGB): deklaratorisch. Kannkaufmann (§§ 2, 3 HGB): Eintragung freiwillig – und dann konstitutiv. GmbH entsteht erst mit Eintragung (§ 11 GmbHG): konstitutiv."},
{id:"b070",s:"blatt",q:"Die Willenserklärung beinhaltet",
 o:["Handlungswillen","Erklärungswillen","Bedeutungswillen","Festlegungswillen","Zahlungswillen"],
 a:[0,1],e:"Subjektiver Tatbestand der Willenserklärung: Handlungswille, Erklärungswille (Erklärungsbewusstsein) und Geschäftswille. „Bedeutungs-“, „Festlegungs-“ oder „Zahlungswille“ sind keine Fachbegriffe."},
{id:"b071",s:"blatt",q:"Eine Willenserklärung kann angefochten werden",
 o:["bei unbewusstem Auseinanderfallen von Wille und Erklärung (Erklärungsirrtum)","bei unbewusstem Auseinanderfallen von Beweggrund zur Abgabe der Erklärung und tatsächlichem Sachstand (Motivirrtum)","bei Irrtum über die Identität des Geschäftspartners","bei Irrtum über die Nationalität des Geschäftspartners","Keine der vorgegebenen Antworten ist richtig."],
 a:[0,2],e:"§ 119 Abs. 1 BGB: Erklärungs- und Inhaltsirrtum berechtigen zur Anfechtung. Der Irrtum über die Identität des Partners (error in persona) ist ein Inhaltsirrtum – anfechtbar. Ein bloßer Motivirrtum ist unbeachtlich (Ausnahme § 119 Abs. 2: verkehrswesentliche Eigenschaften; die Nationalität ist das i. d. R. nicht). ACHTUNG: Das Lösungsblatt kreuzt nur A an."},
{id:"b072",s:"blatt",q:"Die Anfechtung bewirkt",
 o:["Bedeutungslosigkeit der eigenen Willenserklärung","Nichtigkeit der eigenen Willenserklärung für die Zukunft","Nichtigkeit der eigenen Willenserklärung von Anfang an","Nichtigkeit des Vertragswerks von Anfang an","Nichtigkeit des Vertragswerks für die Zukunft"],
 a:[2,3],e:"§ 142 Abs. 1 BGB: Das angefochtene Rechtsgeschäft ist als von Anfang an (ex tunc) nichtig anzusehen – damit entfällt auch der Vertrag rückwirkend."},
{id:"b073",s:"blatt",q:"Eine empfangsbedürftige Willenserklärung wird wirksam,",
 o:["wenn sie geäußert wird","wenn sie zugeht","3 Tage nach Äußerung","wenn sie schriftlich fixiert ist","Keine der vorgegebenen Antworten ist richtig."],
 a:[1],e:"§ 130 Abs. 1 BGB: mit Zugang beim Empfänger."},
{id:"b074",s:"blatt",q:"Missverständliche empfangsbedürftige Willenserklärungen sind auszulegen",
 o:["nach dem Verständnis des Erklärenden","nach dem Verständnis des Erklärungsempfängers","wie sie der Empfänger unter Berücksichtigung aller Umstände, insbesondere der Verkehrssitte, versteht (verstehen durfte)","wie sie ein normaler rechtsunkundiger Mensch verstehen würde","wie sie ein juristisch Gebildeter verstehen würde"],
 a:[2],e:"§§ 133, 157 BGB: Auslegung nach dem objektiven Empfängerhorizont – wie ein verständiger Empfänger die Erklärung nach Treu und Glauben mit Rücksicht auf die Verkehrssitte verstehen durfte."},
{id:"b075",s:"blatt",q:"Ein Vertrag besteht aus",
 o:["2 Willenserklärungen","2 übereinstimmenden Willenserklärungen","Angebot und Annahme","möglicherweise mehr als 2 übereinstimmenden Willenserklärungen","Keine der vorgegebenen Antworten ist richtig."],
 a:[1,2,3],e:"Ein Vertrag kommt durch übereinstimmende Willenserklärungen (Angebot und Annahme, §§ 145 ff.) zustande. Bei mehreren Parteien (z. B. Gesellschaftsvertrag) können es mehr als zwei sein. „2 Willenserklärungen“ allein reicht nicht – sie müssen übereinstimmen."},
{id:"b076",s:"blatt",q:"Ein Angebot im Schaufenster eines Ladens ist",
 o:["eine Angebotserklärung zum Abschluss eines Kaufvertrages","eine vorweg genommene Annahmeerklärung des Kaufmanns","eine Angebotserklärung an einen unbestimmten Personenkreis","eine Aufforderung zur Abgabe eines Kaufvertragsangebots","Keine der vorgegebenen Antworten ist richtig."],
 a:[3],e:"Schaufensterauslagen, Kataloge, Speisekarten: invitatio ad offerendum – der Händler will sich nicht gegenüber beliebig vielen Kunden binden."},
{id:"b077",s:"blatt",q:"Bedingungsfeindliche Rechtsgeschäfte sind",
 o:["der Kaufvertrag über Grundstücke","das Schenkungsversprechen","die Auflassung","die Übereignung nach §§ 929 ff. BGB","jede Verfügung"],
 a:[2],e:"Die Auflassung kann nicht unter einer Bedingung oder Zeitbestimmung erklärt werden (§ 925 Abs. 2 BGB). Kaufvertrag, Schenkungsversprechen und Übereignung beweglicher Sachen (Eigentumsvorbehalt!) sind bedingungsfähig."},
{id:"b078",s:"blatt",q:"Der Grundsatz von Treu und Glauben",
 o:["gilt nur im Privatrecht","besagt, dass Verträge auf jeden Fall zu erfüllen sind","besagt, dass in Ausnahmefällen ein Recht verwirkt sein kann","verbietet Argumente des Schuldners, die zu seinem bisherigen Verhalten im Widerspruch stehen","verbietet generell Argumente eines Schuldners zum Nachteil des rechtsunkundigen Gläubigers"],
 a:[2,3],e:"§ 242 BGB gilt als allgemeiner Rechtsgrundsatz auch im öffentlichen Recht und Steuerrecht. Ausprägungen: Verwirkung und das Verbot widersprüchlichen Verhaltens (venire contra factum proprium)."},
{id:"b079",s:"blatt",q:"Welche der folgenden Aussagen über Schuldverhältnisse ist/sind richtig?",
 o:["An einem Schuldverhältnis sind immer mindestens 2 Personen beteiligt.","Es ist in Ausnahmefällen möglich, dass an einem Schuldverhältnis nur eine Person beteiligt ist.","Schuldverhältnisse können nur durch Vertrag begründet werden.","Die an einem Schuldverhältnis beteiligten Personen werden Gläubiger und Schuldner genannt.","Ausnahmsweise kann ein Schuldverhältnis durch die Willenserklärung einer Person entstehen."],
 a:[0,3,4],e:"Ein Schuldverhältnis besteht zwischen Gläubiger und Schuldner (§ 241) – immer mindestens zwei Personen. Es entsteht durch Vertrag, Gesetz (z. B. § 823) oder ausnahmsweise durch einseitiges Rechtsgeschäft (Auslobung, § 657)."},
{id:"b080",s:"blatt",q:"Der Abstraktionsgrundsatz besagt, dass",
 o:["schuldrechtliche Verpflichtungen auch erfüllt werden müssen","sich die Erfüllungshandlung nach der wirksamen schuldrechtlichen Verpflichtung richtet","ein wirksamer schuldrechtlicher Anspruch zugleich auch zu einer Verpflichtungshandlung führt","ein wirksames Schuldverhältnis keinerlei Auswirkung auf die Wirksamkeit oder Unwirksamkeit der Erfüllungshandlung hat","die Wirksamkeit einer schuldrechtlichen Verpflichtung und die Wirksamkeit der in Ausführung dieser Verpflichtung vollzogenen Erfüllung jeweils getrennt zu beurteilen sind"],
 a:[3,4],e:"Verpflichtungs- und Verfügungsgeschäft sind in ihrer Wirksamkeit voneinander unabhängig (Abstraktion) und getrennt zu prüfen."},
{id:"b081",s:"blatt",q:"Die Abtretung einer Forderung, § 398 BGB,",
 o:["kann nur mit Zustimmung des Schuldners erfolgen","ist eine Verfügung","erfolgt durch einseitige empfangsbedürftige Willenserklärung","muss dem Schuldner angezeigt werden","kann vertraglich ausgeschlossen werden"],
 a:[1,4],e:"Die Abtretung ist ein Verfügungsvertrag zwischen Alt- und Neugläubiger; Zustimmung oder Anzeige an den Schuldner sind nicht nötig (dieser wird über §§ 406 ff. geschützt). Ein vertraglicher Ausschluss ist möglich (§ 399 Alt. 2; Ausnahme § 354a HGB)."},
{id:"b082",s:"blatt",q:"Eine befreiende Schuldübernahme erfordert",
 o:["keinerlei Mitwirkung des Gläubigers","die Beteiligung des Gläubigers in Form einer Willenserklärung","immer einen Vertrag zwischen dem neuen Schuldner und dem Gläubiger","immer ein zweiseitiges Rechtsgeschäft, welches als Verfügung zu klassifizieren ist","immer die Mitwirkung und Willenserklärung des neuen Schuldners"],
 a:[1,3,4],e:"Zwei Wege: Vertrag Gläubiger–Übernehmer (§ 414) oder Vertrag Schuldner–Übernehmer mit Genehmigung des Gläubigers (§ 415). Der Gläubiger muss also immer mitwirken, der neue Schuldner auch. Die Schuldübernahme ist ein Verfügungsgeschäft über die Forderung."},
{id:"b083",s:"blatt",q:"A schuldet dem B 1.000 €. F, ein Freund von A, erfährt von der Schuld seines Freundes und vereinbart mit B, dass er die Schuld anstelle des A übernimmt. A widerspricht, weil er sich nichts schenken lassen will. Die Erklärung des F ist: (Sachverhalt teilweise rekonstruiert)",
 o:["unwirksam, da A widerspricht","wirksam, weil A die Leistung nicht „in Person“ zu leisten hat (vgl. § 267 BGB)","unwirksam, weil (ähnlich der Bürgschaftserklärung) eine mündliche Zusage des B nicht ausreicht","ein Schuldbeitritt, weil A immer noch selbst leisten will","eine befreiende Schuldübernahme, obwohl A sich nichts schenken lassen will"],
 a:[1,4],e:"Eine Schuldübernahme durch Vertrag zwischen Gläubiger und Übernehmer (§ 414 BGB) braucht die Zustimmung des Altschuldners nicht. Auch ein Dritter darf leisten, wenn der Schuldner nicht in Person leisten muss (§ 267). Die Schuldübernahme ist formfrei."},
{id:"b084",s:"blatt",q:"Heute in Deutschland geltende Rechtsquellen sind",
 o:["die Bibel","die Moralvorstellungen der Kirche","Gesetze des Reichstages","Gesetze des Bundestages","Gesetze der Landtage"],
 a:[2,3,4],e:"Vorkonstitutionelles Recht gilt fort, soweit es dem Grundgesetz nicht widerspricht (Art. 123 GG) – z. B. BGB und HGB wurden vom Reichstag beschlossen. Religion und Moral sind keine Rechtsquellen."},
{id:"b085",s:"blatt",q:"Unter Gesetz versteht man",
 o:["vom Bundestag gesetzte Rechtsnormen","vom Landtag gesetzte Rechtsnormen","vom Kreistag gesetzte Rechtsnormen","von der Bundesregierung gesetzte Rechtsnormen","von der Stadtverwaltung gesetzte Rechtsnormen (Satzung)"],
 a:[0,1,3],e:"Lösung laut Lösungsblatt: A, B, D. Parlamentsgesetze sind Gesetze im formellen und materiellen Sinn; Rechtsverordnungen der Bundesregierung (Art. 80 GG) sind Gesetze im materiellen Sinn. Satzungen werden hier nicht als „Gesetz“ gezählt (sie sind autonomes Recht der Selbstverwaltung)."},
{id:"b086",s:"blatt",q:"Unter Recht versteht man",
 o:["geschriebene Gesetze","seit langer Zeit geltenden Rechtsbrauch (Gewohnheitsrecht)","die Auffassung aller billig und gerecht Denkenden","was dem Volke nutzt","die Auffassung der den Staat tragenden Parteien"],
 a:[0,1],e:"Rechtsquellen sind geschriebenes Recht (Gesetze, Verordnungen, Satzungen) und Gewohnheitsrecht. Die „Auffassung aller billig und gerecht Denkenden“ ist ein Maßstab für die Sittenwidrigkeit (§ 138), aber keine Rechtsquelle."},
{id:"b087",s:"blatt",q:"Gesetze im formellen Sinne haben ihre Bezeichnung deshalb, weil",
 o:["sie in dem von der Verfassung vorgesehenen Verfahren zustande gekommen sind","sie einer gewissen äußeren Form bedürfen","sie in formeller Weise verkündet werden","über sie in besonders vorgeschriebener Form abgestimmt wird","Keine der vorgegebenen Antworten ist richtig."],
 a:[0],e:"Formelles Gesetz = vom Parlament im verfassungsmäßig vorgesehenen Gesetzgebungsverfahren beschlossen (Art. 76 ff. GG)."},
{id:"b088",s:"blatt",q:"Gesetze im materiellen Sinne haben ihre Bezeichnung deshalb, weil",
 o:["sie eine ganz bestimmte Materie regeln","sie allgemeingültig sind, also nicht (zwingend) auf dem von der Verfassung vorgeschriebenen formellen Gesetzgebungsgang zustande gekommen sind","sie nicht für jedermann gelten","sie nur für eine bestimmte Personengruppe gelten","Keine der vorgegebenen Antworten ist richtig."],
 a:[1],e:"Materielles Gesetz = jede abstrakt-generelle, allgemeinverbindliche Rechtsnorm – unabhängig davon, wer sie erlassen hat (auch Rechtsverordnungen und Satzungen)."},
{id:"b089",s:"blatt",q:"Unsere Rechtsordnung unterteilt sich in",
 o:["öffentliches Recht","privates Recht","Gewohnheitsrecht","Strafrecht","Steuerrecht"],
 a:[0,1],e:"Grundunterscheidung: öffentliches Recht und Privatrecht. Straf- und Steuerrecht sind Teile des öffentlichen Rechts; Gewohnheitsrecht ist eine Rechtsquelle."},
{id:"b090",s:"blatt",q:"Das BGB ist der Reihe nach eingeteilt in",
 o:["Allg. Teil, Familienrecht, Sachenrecht, Erbrecht, Schuldrecht","Allg. Teil, Schuldrecht, Sachenrecht, Familienrecht, Erbrecht","Allg. Teil, Erbrecht, Strafrecht, Familienrecht, Sachenrecht","Allg. Teil, Öffentliches Recht, Sachenrecht, Strafrecht, Erbrecht","Allg. Teil, Erbrecht, Sachenrecht, Familienrecht, Schuldrecht"],
 a:[1],e:"Buch 1 Allgemeiner Teil, Buch 2 Schuldrecht, Buch 3 Sachenrecht, Buch 4 Familienrecht, Buch 5 Erbrecht."},
{id:"b091",s:"blatt",q:"Das Steuerrecht hat folgenden Bezug zum Zivilrecht:",
 o:["Das Steuerrecht verweist häufig auf die Vorschriften im Zivilrecht.","Die zivilrechtlichen Begriffe haben im Steuerrecht grds. dieselbe Bedeutung.","Das Steuerrecht übernimmt grds. die zivilrechtliche Zuordnung einer bestimmten Sache zu einer bestimmten Person.","Das Steuerrecht kennt sowohl zivilrechtliches wie wirtschaftliches Eigentum.","Das Steuerrecht besteuert nur vom Privatrecht gebilligte rechtliche Erfolge."],
 a:[0,1,2,3],e:"Das Steuerrecht knüpft an Zivilrecht an (§ 39 Abs. 1 AO), kennt aber das wirtschaftliche Eigentum (§ 39 Abs. 2 AO). Auch gesetz- oder sittenwidrige Geschäfte werden besteuert, soweit sie wirtschaftlich vollzogen werden (§ 40, § 41 AO)."},
{id:"b092",s:"blatt",q:"Was gehört zu den Rechtsquellen?",
 o:["Autonome Satzungen","Die Satzungen, die ein Verein zur Regelung seines Vereinslebens aufstellt","Gewohnheitsrecht","Einkommensteuer-Richtlinien (EStR)","Rechtsverordnungen"],
 a:[0,2,4],e:"Autonome Satzungen öffentlich-rechtlicher Körperschaften (z. B. Gemeinden), Gewohnheitsrecht und Rechtsverordnungen sind Rechtsquellen. Vereinssatzungen binden nur die Mitglieder (privatrechtlich). Richtlinien sind Verwaltungsvorschriften – sie binden nur die Verwaltung, nicht Bürger und Gerichte."},
{id:"b093",s:"blatt",q:"Wodurch erlangen die folgenden Rechtssubjekte ihre volle Rechtsfähigkeit?",
 o:["Eine juristische Person u. a. durch Eintragung oder Gesetz","Eine natürliche Person mit Eintritt der Volljährigkeit","Eine OHG durch Eintragung ins Handelsregister","Ein Verein mit Beschluss der Satzung","Eine natürliche Person mit Vollendung der Geburt"],
 a:[0,4],e:"Natürliche Person: § 1 BGB. Juristische Personen: durch Eintragung (e.V., GmbH, AG), staatliche Verleihung/Anerkennung oder Gesetz. Die OHG ist keine juristische Person. Der Verein wird erst mit Eintragung rechtsfähig (§ 21)."},
{id:"b094",s:"blatt",q:"Teilrechtsfähig sind:",
 o:["Das ungeborene Kind (nasciturus)","Der Minderjährige, der im Rahmen des § 112 BGB tätig ist","Der eingetragene Verein","Natürliche Personen, die gem. § 114 BGB z. B. wegen Trunksucht entmündigt sind","Keine der vorgegebenen Antworten ist richtig."],
 a:[4],e:"Lösung laut Lösungsblatt: E. Der Minderjährige und der e.V. sind voll rechtsfähig, eine Entmündigung gibt es seit 1992 nicht mehr (§ 114 BGB a. F. ist aufgehoben). Der Nasciturus ist nach § 1 BGB noch nicht rechtsfähig; nur einzelne Vorschriften schützen ihn (z. B. § 1923 Abs. 2, § 844 Abs. 2) – daher wird er hier nicht als „teilrechtsfähig“ gezählt."},
{id:"b095",s:"blatt",q:"Der 6-jährige Peter kauft ohne Wissen seiner Eltern von seinem Taschengeld eine neue Luftpumpe für sein Fahrrad. Welche Aussage(n) ist/sind richtig?",
 o:["Peter bedarf der Genehmigung der gesetzlichen Vertreter.","Peter bedarf der Einwilligung der gesetzlichen Vertreter.","Der Kauf der Luftpumpe ist nichtig.","Peter gibt selbst eine Willenserklärung ab (Taschengeldparagraph).","Peter kann keine Willenserklärung abgeben."],
 a:[2,4],e:"Mit 6 Jahren ist Peter geschäftsunfähig (§ 104 Nr. 1); seine Willenserklärung ist nichtig (§ 105 Abs. 1) – weder Einwilligung noch Genehmigung helfen, § 110 gilt erst ab 7."},
{id:"b096",s:"blatt",q:"Was ist ein 13-Jähriger?",
 o:["Minderjährig und rechtsfähig","Bedingt straffähig (bedingt strafmündig)","Bedingt deliktsfähig","Beschränkt geschäftsfähig","Teilrechtsfähig"],
 a:[0,2,3],e:"Minderjährig (§ 2), voll rechtsfähig (§ 1), bedingt deliktsfähig (§ 828 Abs. 3), beschränkt geschäftsfähig (§ 106). Strafmündig erst ab 14 (§ 19 StGB) – „bedingt strafmündig“ gibt es nicht."},
{id:"b097",s:"blatt",q:"Die 9-jährige Petra bekommt von ihrer Oma eine neue Musikkassette für ihr Tape. Mutter freut sich, Vater nicht.",
 o:["Petra kann das Schenkungsangebot annehmen.","Petra kann hierbei keine wirksame Willenserklärung abgeben.","Die Eltern haben als gesetzliche Vertreter für Petra das Schenkungsangebot angenommen.","Petra erwirbt Eigentum an der Kassette.","Die Schenkung i. S. d. § 516 BGB ist ein zweiseitiges Rechtsgeschäft."],
 a:[0,3,4],e:"Petra ist beschränkt geschäftsfähig (§ 106). Schenkung und Übereignung sind für sie lediglich rechtlich vorteilhaft (§ 107) – sie braucht ihre Eltern nicht. Die Schenkung ist ein Vertrag (zweiseitiges Rechtsgeschäft)."},
{id:"b098",s:"blatt",q:"Was gehört zu den Rechtsquellen?",
 o:["Friedhofssatzung einer Gemeinde","Umsatzsteuer-Durchführungsverordnung","Erlass des Ministeriums der Finanzen","Gerichtsentscheidung des Bundesfinanzhofs","Satzung des Angelsportvereins e. V."],
 a:[0,1],e:"Gemeindesatzungen (autonomes Recht) und Rechtsverordnungen (UStDV) sind Rechtsquellen. Erlasse sind Verwaltungsvorschriften, Urteile binden grundsätzlich nur die Beteiligten (Ausnahme z. B. § 31 BVerfGG), Vereinssatzungen nur die Mitglieder."},
{id:"b099",s:"blatt",q:"Die Aufrechnung setzt voraus:",
 o:["Gegenseitigkeit der Forderungen","Gleichartigkeit der Leistungen","eine fällige Hauptforderung","eine fällige Gegenforderung","eine Aufrechnungslage"],
 a:[0,1,3,4],e:"§ 387 BGB: Gegenseitigkeit, Gleichartigkeit, die Gegenforderung (mit der man aufrechnet) muss fällig und einredefrei sein, die Hauptforderung muss nur erfüllbar sein. Zusammen heißt das „Aufrechnungslage“; dazu kommt die Aufrechnungserklärung (§ 388)."},
{id:"b100",s:"blatt",q:"Die Abtretung einer Forderung ist",
 o:["ein Verpflichtungsgeschäft","ein Verfügungsgeschäft","ein schuldrechtlicher Vertrag","grundsätzlich formbedürftig","ein Rechtsgeschäft"],
 a:[1,2,4],e:"Die Abtretung (§ 398) ist ein Vertrag, der im Schuldrecht (2. Buch) geregelt ist, aber verfügenden Charakter hat: Die Forderung geht über. Sie ist grundsätzlich formfrei."},

// ===================== Erbrecht / Erbschaftsteuer (Richtig/Falsch) =====================
{id:"e01",s:"erb",q:"Die Erbschaftsteuer für Rheinland-Pfalz und das Saarland wird stets vom Finanzamt Kusel-Landstuhl bearbeitet.",o:RF,a:[0],e:"Richtig (Zentralzuständigkeit des Finanzamts Kusel-Landstuhl für die Erbschaft- und Schenkungsteuer in RLP und im Saarland)."},
{id:"e02",s:"erb",q:"Das Finanzamt Kusel-Landstuhl führt auch stets die Bewertung durch.",o:RF,a:[1],e:"Falsch – Bewertungen (z. B. von Grundbesitz) machen die örtlich zuständigen Finanzämter (Lagefinanzamt)."},
{id:"e03",s:"erb",q:"Die Erbschaftsteuer wird vom Bund verwaltet.",o:RF,a:[1],e:"Falsch – die Erbschaftsteuer ist eine Ländersteuer und wird von den Ländern verwaltet (Art. 106 Abs. 2, Art. 108 GG)."},
{id:"e04",s:"erb",q:"Da der Erblasser Steuerschuldner und Träger ist, ist die Erbschaftsteuer eine direkte Steuer.",o:RF,a:[1],e:"Falsch – Steuerschuldner ist der Erwerber, also der Erbe (§ 20 ErbStG), nicht der Erblasser."},
{id:"e05",s:"erb",q:"Die Regeln zur Erbschaftsteuer gelten voll umfänglich auch für Schenkungen.",o:RF,a:[1],e:"Falsch – sie gelten nur, „soweit nichts anderes bestimmt ist“ (§ 1 Abs. 2 ErbStG); es gibt Ausnahmen."},
{id:"e06",s:"erb",q:"Adoptivkinder gehören zu den Erben 1. Ordnung.",o:RF,a:[0],e:"Richtig – angenommene Kinder sind leiblichen Kindern gleichgestellt (§ 1754 BGB) und damit Abkömmlinge (§ 1924)."},
{id:"e07",s:"erb",q:"Ein Enkel erbt nach dem BGB immer, da er zur ersten Ordnung zählt.",o:RF,a:[1],e:"Falsch – das Repräsentationsprinzip (§ 1924 Abs. 2) schließt ihn aus, solange sein Elternteil (das Kind des Erblassers) lebt."},
{id:"e08",s:"erb",q:"Stiefkinder gehören zu keiner Ordnung und können deshalb nie Erben werden.",o:RF,a:[1],e:"Falsch – „nie“ stimmt nicht: Durch Testament (oder Adoption) können sie Erben werden."},
{id:"e09",s:"erb",q:"Der Erbanfall ist der einzige Erwerb von Todes wegen.",o:RF,a:[1],e:"Falsch – auch Vermächtnis, Pflichtteil, Schenkung auf den Todesfall u. a. sind Erwerbe von Todes wegen (§ 3 ErbStG)."},
{id:"e10",s:"erb",q:"Ein Ehegatte erbt neben Verwandten der 2. Ordnung immer zu 1/2.",o:RF,a:[1],e:"Falsch – bei Zugewinngemeinschaft erhöht sich der Erbteil um 1/4 (§ 1371 Abs. 1), also auf 3/4."},
{id:"e11",s:"erb",q:"Ein Ehegatte kann gesetzlich nicht zusammen mit Abkömmlingen der 3. Ordnung erben.",o:RF,a:[0],e:"Richtig – neben Großeltern erbt der Ehegatte die Hälfte; Anteile, die auf Abkömmlinge der Großeltern fallen würden, erhält der Ehegatte (§ 1931 Abs. 1 S. 2 BGB)."},
{id:"e12",s:"erb",q:"Testierfähig sind alle lebenden Menschen.",o:RF,a:[1],e:"Falsch – erst ab Vollendung des 16. Lebensjahres (§ 2229 Abs. 1 BGB)."},
{id:"e13",s:"erb",q:"Die gesetzliche Erbfolge geht der gewillkürten Erbfolge vor.",o:RF,a:[1],e:"Falsch – andersherum: Testament und Erbvertrag gehen vor; die gesetzliche Erbfolge gilt nur, soweit keine Verfügung von Todes wegen vorliegt."},
{id:"e14",s:"erb",q:"Das Ehegattenerbrecht steht neben dem Verwandtenerbrecht.",o:RF,a:[0],e:"Richtig – der Ehegatte erbt neben den Verwandten (§ 1931 BGB)."},
{id:"e15",s:"erb",q:"Die Zugewinngemeinschaft erhöht den Erbteil des Ehegatten stets um 1/4.",o:RF,a:[0],e:"Richtig laut Quelle – pauschaler Zugewinnausgleich über den erhöhten gesetzlichen Erbteil (§ 1371 Abs. 1 BGB, „erbrechtliche Lösung“)."},
{id:"e16",s:"erb",q:"Ein Testament muss notariell abgeschlossen werden.",o:RF,a:[1],e:"Falsch – es geht auch eigenhändig (handschriftlich und unterschrieben, § 2247 BGB)."},
{id:"e17",s:"erb",q:"Der Nasciturus ist passiv erbfähig.",o:RF,a:[1],e:"Falsch – er ist aktiv erbfähig (kann Erbe werden, § 1923 Abs. 2 BGB)."},
{id:"e18",s:"erb",q:"Eine Erbausschlagung gilt auch für die Abkömmlinge des Ausschlagenden.",o:RF,a:[1],e:"Falsch – das gilt für den Erbverzicht (§ 2349 BGB). Nach einer Ausschlagung rücken die Abkömmlinge nach (§ 1953 Abs. 2)."},
{id:"e19",s:"erb",q:"Ein Erbverzicht geht nur zu Lebzeiten (des Erblassers).",o:RF,a:[0],e:"Richtig – der Erbverzicht ist ein Vertrag mit dem Erblasser (§ 2346 BGB, notariell)."},
{id:"e20",s:"erb",q:"A und B erben zu je 1/2. Was trifft zu? (Antworten D und E ergänzt)",
 o:["Sie bilden eine Erbengemeinschaft.","Sie bilden eine Gesamthandsgemeinschaft.","Sie können bis zur Erbauseinandersetzung nur gemeinsam über den Nachlass bestimmen.","Sie bilden eine Bruchteilsgemeinschaft.","Jeder kann allein über seinen Anteil an einzelnen Nachlassgegenständen verfügen."],
 a:[0,1,2],e:"Mehrere Erben bilden eine Erbengemeinschaft (§ 2032) – eine Gesamthandsgemeinschaft, keine Bruchteilsgemeinschaft. Über Nachlassgegenstände verfügen sie nur gemeinschaftlich (§ 2040); über den Anteil an einzelnen Gegenständen kann keiner allein verfügen (§ 2033 Abs. 2)."},
{id:"e21",s:"erb",q:"Haben Erblasser und Erbe ihren Wohnsitz und gewöhnlichen Aufenthalt im Ausland, tritt stets die beschränkte Steuerpflicht in Kraft.",o:RF,a:[1],e:"Falsch wegen „stets“ – z. B. erweiterte unbeschränkte Steuerpflicht für deutsche Staatsangehörige bis 5 Jahre nach Wegzug (§ 2 Abs. 1 Nr. 1 b ErbStG); beschränkt steuerpflichtig ist man zudem nur mit Inlandsvermögen."},
{id:"e22",s:"erb",q:"Nur wenn Erblasser und Erbe die Merkmale der unbeschränkten Steuerpflicht erfüllen, tritt das Weltvermögensprinzip in Kraft.",o:RF,a:[1],e:"Falsch – „und“ stimmt nicht: Es reicht, wenn einer von beiden Inländer ist (§ 2 Abs. 1 Nr. 1 ErbStG)."},
{id:"e23",s:"erb",q:"Als Bewertungsstichtag ist stets der Todeszeitpunkt maßgebend.",o:RF,a:[1],e:"Falsch – bei Schenkungen ist es der Zeitpunkt der Ausführung der Zuwendung (§ 9 Abs. 1 Nr. 2, § 11 ErbStG)."}
];
